/* The heap overview:
 *
 * HEAP_REGION0_START                        g_allocable_vaddr_start
 *     :
 *     : g_mmheap (CONFIG_ESP32_SPIRAM)
 *     :
 * HEAP_REGION0_END                          g_allocable_vaddr_end
 *     :
 *---------------------------------------------------------------------
 * if CONFIG_MM_KERNEL_HEAP && MM_USER_HEAP_IRAM
 *
 * HEAP_REGION1_START                        _sheap
 *     :
 *     : g_iheap (CONFIG_XTENSA_IMEM_USE_SEPARATE_HEAP)
 *     :
 * HEAP_REGION1_START + CONFIG_XTENSA_IMEM_REGION_SIZE
 *     :
 *     : g_mmheap region1
 *     :
 * HEAP_REGION1_END                          3fcc fff0
 *     :
 * HEAP_REGION2_START                        3fcd 0000
 *     :
 *     : g_mmheap region2
 *     :
 * HEAP_REGION2_END                          dram0_rtos_reserved_start
 *     :
 *---------------------------------------------------------------------
 * if !CONFIG_MM_KERNEL_HEAP || !MM_USER_HEAP_IRAM
 *
 * HEAP_REGION1_START                            _sheap
 *     :
 *     : g_iheap (CONFIG_XTENSA_IMEM_USE_SEPARATE_HEAP)
 *     :
 * HEAP_REGION1_START + CONFIG_XTENSA_IMEM_REGION_SIZE
 *     :
 *     : g_mmheap region1
 *     :
 * HEAP_REGION1_END                          dram0_rtos_reserved_start
 *     :
 *---------------------------------------------------------------------
 */

#ifdef CONFIG_MM_KERNEL_HEAP
#  define HEAP_REGION1_END      0x3fccfff0
#  define HEAP_REGION2_START    0x3fcd0000
#endif

#ifdef CONFIG_XTENSA_IMEM_USE_SEPARATE_HEAP
#  define XTENSA_IMEM_REGION_SIZE  CONFIG_XTENSA_IMEM_REGION_SIZE
#else
#  define XTENSA_IMEM_REGION_SIZE  0
#endif

/****************************************************************************
 * Name: esp32s3_sp_dram
 *
 * Description:
 *   Check if the stack pointer is in DRAM.
 *
 ****************************************************************************/

static inline bool IRAM_ATTR esp32s3_sp_dram(uint32_t sp)
{
  return (sp >= SOC_DRAM_LOW + 0x10 && sp < SOC_DRAM_HIGH - 0x10);
}

/****************************************************************************
 * Name: esp32s3_ptr_extram
 *
 * Description:
 *   Check if the buffer comes from the external RAM
 *
 ****************************************************************************/

static inline bool IRAM_ATTR esp32s3_ptr_extram(const void *p)
{
  return ((intptr_t)p >= SOC_EXTRAM_DATA_LOW &&
          (intptr_t)p < SOC_EXTRAM_DATA_HIGH);
}

/****************************************************************************
 * Name: esp32s3_ptr_iram
 *
 * Description:
 *   Check if the pointer is in IRAM
 *
 ****************************************************************************/

static inline bool IRAM_ATTR esp32s3_ptr_iram(const void *p)
{
  return ((intptr_t)p >= SOC_IRAM_LOW && (intptr_t)p < SOC_IRAM_HIGH);
}

