  finfo("buffer=%p buflen=%d\n", buffer, (int)buflen);

  DEBUGASSERT(buffer != NULL && buflen > 0);
  offset = filep->f_pos;

  /* Recover our private data from the struct file instance */

  procfile = (FAR struct meminfo_file_s *)filep->f_priv;
  DEBUGASSERT(procfile);

  /* The first line is the headers */

  linesize  = procfs_snprintf(procfile->line, MEMINFO_LINELEN,
                              "%11s%11s%11s%11s%11s%7s%7s%s\n",
                              "total", "used", "free", "maxused",
                              "maxfree", "nused", "nfree", " name");

  copysize  = procfs_memcpy(procfile->line, linesize, buffer, buflen,
                            &offset);
  totalsize = copysize;

  flags = spin_lock_irqsave(&g_procfs_meminfo_lock);
  entry = g_procfs_meminfo;

  while (entry != NULL && buflen > 0)
    {
      entry->refs++;
      spin_unlock_irqrestore(&g_procfs_meminfo_lock, flags);

      /* Get heap information (without holding lock) */

      if (entry->mallinfo)
