 */
void agent_trace_step(agent_trace_t* t, int iteration,
    const char* tool_name, uint32_t latency_ms,
    int llm_ok);

/**
 * End the trace and log the summary.
 */
void agent_trace_end(agent_trace_t* t, int status);

