   374	        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
   375	            rb->data, raw_cap);
   376	    } else {
   377	        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
   378	            rb->data, raw_cap);
