    68	int resp_buf_init(resp_buf_t* rb, size_t initial_cap)
    69	{
    70	    rb->data = calloc(1, initial_cap);
    71	    if (!rb->data)
    72	        return ERROR;
    73	    rb->len = 0;
    74	    rb->cap = initial_cap;
    75	    return OK;
    76	}
    77	
    78	int resp_buf_append(resp_buf_t* rb, const char* data, size_t len)
    79	{
    80	    while (rb->len + len >= rb->cap) {
    81	        size_t new_cap = rb->cap * 2;
    82	        if (new_cap > AGENT_LLM_MAX_RESP_SIZE) {
    83	            syslog(LOG_ERR, "llm: resp_buf exceeded %d limit\n",
    84	                AGENT_LLM_MAX_RESP_SIZE);
    85	            return ERROR;
    86	        }
    87	        char* tmp = realloc(rb->data, new_cap);
    88	        if (!tmp)
    89	            return ERROR;
    90	        rb->data = tmp;
    91	        rb->cap = new_cap;
    92	    }
    93	    memcpy(rb->data + rb->len, data, len);
    94	    rb->len += len;
    95	    rb->data[rb->len] = '\0';
    96	    return OK;
    97	}
