   283	/* ── Clock-safe elapsed time calculation ───────────────────── */
   284	
   285	static inline uint32_t calc_elapsed_ms(const struct timeval* t0,
   286	    const struct timeval* t1)
   287	{
   288	    int32_t sec_diff = (int32_t)(t1->tv_sec - t0->tv_sec);
   289	    int32_t usec_diff = (int32_t)(t1->tv_usec - t0->tv_usec);
   290	
   291	    /* Clock went backwards (NTP jump, manual adjustment) */
   292	    if (sec_diff < 0) {
   293	        syslog(LOG_WARNING, "[%s] Clock went backwards, ignoring\n", TAG);
   294	        return 0;
   295	    }
   296	
   297	    /* Microsecond borrow */
   298	    if (usec_diff < 0) {
   299	        sec_diff--;
   300	        usec_diff += 1000000;
   301	    }
   302	
   303	    if (sec_diff < 0) {
   304	        return 0;
   305	    }
   306	
   307	    return (uint32_t)sec_diff * 1000 + (uint32_t)usec_diff / 1000;
   308	}
