   315	/* Build OpenAI-format assistant message with tool_calls at the top level */
   316	static void add_assistant_message(cJSON* messages, const llm_response_t* resp)
   317	{
   318	    cJSON* asst_msg = cJSON_CreateObject();
   319	    cJSON_AddStringToObject(asst_msg, "role", "assistant");
   320	
   321	    if (resp->text && resp->text_len > 0) {
   322	        cJSON_AddStringToObject(asst_msg, "content", resp->text);
   323	    } else {
   324	        cJSON_AddNullToObject(asst_msg, "content");
   325	    }
   326	
   327	    /* Kimi thinking mode: echo back reasoning_content or the API returns 400 */
   328	    if (resp->reasoning_content && resp->reasoning_content[0]) {
   329	        cJSON_AddStringToObject(asst_msg, "reasoning_content",
   330	            resp->reasoning_content);
   331	    }
   332	
   333	    if (resp->call_count > 0) {
   334	        cJSON* tool_calls = cJSON_CreateArray();
   335	        for (int i = 0; i < resp->call_count; i++) {
   336	            const llm_tool_call_t* call = &resp->calls[i];
   337	            cJSON* tc = cJSON_CreateObject();
   338	            cJSON_AddStringToObject(tc, "id", call->id);
   339	            cJSON_AddStringToObject(tc, "type", "function");
   340	
   341	            cJSON* func_obj = cJSON_CreateObject();
   342	            cJSON_AddStringToObject(func_obj, "name", call->name);
   343	            cJSON_AddStringToObject(func_obj, "arguments",
   344	                call->input ? call->input : "{}");
   345	            cJSON_AddItemToObject(tc, "function", func_obj);
   346	            cJSON_AddItemToArray(tool_calls, tc);
   347	        }
   348	        cJSON_AddItemToObject(asst_msg, "tool_calls", tool_calls);
   349	    }
   350	
   351	    cJSON_AddItemToArray(messages, asst_msg);
   352	}
