   354	/* Auto-inject channel/chat_id into cron_add input JSON. */
   355	static char* inject_cron_context(const char* tool_name,
   356	    const char* input_json, const char* channel, const char* chat_id)
   357	{
   358	    if (strcmp(tool_name, "cron_add") != 0) {
   359	        return NULL;
   360	    }
   361	    if (!channel || !channel[0] || !chat_id || !chat_id[0]) {
   362	        return NULL;
   363	    }
   364	
   365	    cJSON* root = cJSON_Parse(input_json);
   366	    if (!root) {
   367	        return NULL;
   368	    }
   369	
   370	    cJSON_DeleteItemFromObject(root, "channel");
   371	    cJSON_DeleteItemFromObject(root, "chat_id");
   372	    cJSON_AddStringToObject(root, "channel", channel);
   373	    cJSON_AddStringToObject(root, "chat_id", chat_id);
   374	
   375	    char* patched = cJSON_PrintUnformatted(root);
   376	    cJSON_Delete(root);
   377	    return patched;
   378	}
