  1315	            if (llm_call_timed_out(latency_ms)) {
  1316	                syslog(LOG_WARNING,
  1317	                    "[%s] LLM watchdog: call failed after %" PRIu32 " ms "
  1318	                    "(limit %ds)\n",
  1319	                    TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
