   140	static void *agent_loop_alloc_psram(size_t size)
   141	{
   142	    void *discarded[64];
   143	    int count = 0;
   144	    void *ptr;
   145	
   146	    while (count < (int)(sizeof(discarded) / sizeof(discarded[0]))) {
   147	        ptr = calloc(1, size);
   148	        if (!ptr || agent_loop_mem_kind(ptr)[0] == 'P') {
   149	            while (count > 0) {
   150	                free(discarded[--count]);
   151	            }
   152	            return ptr;
   153	        }
   154	
   155	        discarded[count++] = ptr;
   156	    }
   157	
   158	    while (count > 0) {
   159	        free(discarded[--count]);
   160	    }
   161	
   162	    return NULL;
   163	}
   164	
   165	static int agent_loop_pool_init_psram(agent_mem_pool_t *pool,
   166	    size_t buf_size, int count)
   167	{
   168	    if (count > AGENT_POOL_SLOTS) {
   169	        count = AGENT_POOL_SLOTS;
   170	    }
   171	
   172	    memset(pool, 0, sizeof(*pool));
   173	    pool->buf_size = buf_size;
   174	    pool->count = count;
   175	    pthread_mutex_init(&pool->lock, NULL);
   176	    for (int i = 0; i < count; i++) {
   177	        pool->buffers[i] = agent_loop_alloc_psram(buf_size);
   178	        if (!pool->buffers[i]) {
   179	            for (int j = 0; j < i; j++) {
   180	                free(pool->buffers[j]);
   181	            }
   182	            pthread_mutex_destroy(&pool->lock);
   183	            return ERROR;
   184	        }
   185	    }
   186	    return OK;
   187	}
