   646	
   647	static void pause_all_cpu(void)
   648	{
   649	  cpu_set_t cpuset = (1 << CONFIG_SMP_NCPUS) - 1;
   650	  int delay = CONFIG_ASSERT_PAUSE_CPU_TIMEOUT;
   651	  int ncpus = 0;
   652	
   653	  CPU_CLR(this_cpu(), &cpuset);
   654	  nxsched_smp_call_async(cpuset, &g_call_data);
   655	  this_cpu_var_smp(g_cpu_paused) = true;
   656	
   657	  /* Check if all CPUs paused with timeout */
   658	
   659	  while (delay-- > 0 && ncpus < CONFIG_SMP_NCPUS)
   660	    {
   661	      if (per_cpu_var_smp(g_cpu_paused, ncpus))
   662	        {
   663	          ncpus++;
   664	        }
   665	      else
   666	        {
   667	          up_mdelay(1);
   668	        }
   669	    }
   670	}
