   441	/* ── Failure tracking ─────────────────────────────────────── */
   442	
   443	void llm_router_report_failure(int index)
   444	{
   445	    if (index < 0 || index >= LLM_ROUTER_MAX_BACKENDS) {
   446	        return;
   447	    }
   448	
   449	    pthread_mutex_lock(&s_router_lock);
   450	
   451	    llm_backend_t* b = &s_backends[index];
   452	    uint64_t now = router_monotonic_sec();
   453	
   454	    /* Debounce: only count if outside rapid-fire window */
   455	    if (now - b->last_fail_ts >= BACKOFF_DEBOUNCE_SEC) {
   456	        b->fail_count++;
   457	    }
   458	    b->last_fail_ts = now;
   459	    b->total_failures++;
   460	
   461	    /* Exponential backoff starting from the 2nd failure.
   462	     * First failure gets no backoff — transient 502/503 from load
   463	     * balancers are common and usually resolve within seconds.
   464	     * Backoff schedule: 0s, 2s, 4s, 8s, ... up to 60s max. */
   465	    uint32_t backoff = 0;
   466	    if (b->fail_count >= 2) {
   467	        uint32_t shift = b->fail_count - 2;
   468	        if (shift > 5) shift = 5;  /* cap shift to avoid UB */
   469	        backoff = (1u << shift) * 2;
   470	        if (backoff > 60) {
   471	            backoff = 60;
   472	        }
   473	    }
   474	    b->backoff_until = backoff > 0 ? now + backoff : 0;
   475	
   476	    syslog(LOG_WARNING, "[%s] Backend %d failure count: %d (backoff %" PRIu32 ")\n",
   477	        TAG, index, b->fail_count, backoff);
   478	
   479	    pthread_mutex_unlock(&s_router_lock);
   480	}
