      size_t size = mm_malloc_size(heap, mem);
#ifdef CONFIG_MM_FILL_ALLOCATIONS
      memset(mem, MM_FREE_MAGIC, size);
#endif
      UNUSED(size);
      kasan_poison(mem, size);
    }

