size_t mm_malloc_size(FAR struct mm_heap_s *heap, FAR void *mem)
{
  FAR struct mm_freenode_s *node;
  ssize_t size;
  bool bypass;

  bypass = kasan_bypass(true);
#ifdef CONFIG_MM_HEAP_MEMPOOL
  if (heap->mm_mpool)
    {
      size = mempool_multiple_alloc_size(heap->mm_mpool, mem);
      if (size >= 0)
        {
          kasan_bypass(bypass);

#  if CONFIG_MM_NODE_GUARDSIZE != 0
          DEBUGASSERT(size % MM_ALIGN == 0);
#  endif

          return size;
        }
    }
#endif

  /* Protect against attempts to query a NULL reference */

  if (!mem)
    {
      return 0;
    }

  /* Map the memory chunk into a free node */

  node = (FAR struct mm_freenode_s *)((FAR char *)mem - MM_SIZEOF_ALLOCNODE);

  /* Sanity check against double-frees */

  DEBUGASSERT(MM_NODE_IS_ALLOC(node));

  size = MM_SIZEOF_NODE(node) - MM_ALLOCNODE_OVERHEAD;

  kasan_bypass(bypass);

#if CONFIG_MM_NODE_GUARDSIZE != 0
  DEBUGASSERT(size % MM_ALIGN == 0);
#endif

  return size;
}

