   484	/* ── Latency tracking ─────────────────────────────────────── */
   485	
   486	void llm_router_report_latency(int index, uint32_t latency_ms)
   487	{
   488	    if (index < 0 || index >= LLM_ROUTER_MAX_BACKENDS) {
   489	        return;
   490	    }
   491	
   492	    pthread_mutex_lock(&s_router_lock);
   493	    llm_backend_t* b = &s_backends[index];
   494	
   495	    /* Exponential moving average: new = 0.7 * old + 0.3 * sample */
   496	    if (b->avg_latency_ms == 0) {
   497	        b->avg_latency_ms = latency_ms;
   498	    } else {
   499	        b->avg_latency_ms = (b->avg_latency_ms * 7 + latency_ms * 3) / 10;
   500	    }
   501	    pthread_mutex_unlock(&s_router_lock);
   502	}
