struct agent_heap_diag_s
{
    size_t internal_free;
    size_t internal_largest;
    size_t psram_free;
    size_t psram_largest;
};

static const char *agent_loop_mem_kind(const void *ptr)
{
    uintptr_t addr = (uintptr_t)ptr;

    return addr >= AGENT_LOOP_PSRAM_LOW && addr < AGENT_LOOP_PSRAM_HIGH ?
        "PSRAM" : "INTERNAL";
}

static void agent_loop_heap_diag_node(struct mm_allocnode_s *node,
    void *arg)
{
    struct agent_heap_diag_s *stats = arg;
    size_t size;
    size_t *free_bytes;
    size_t *largest;

    if (!MM_NODE_IS_FREE(node)) {
        return;
    }

    size = MM_SIZEOF_NODE(node);
    if (agent_loop_mem_kind(node)[0] == 'P') {
        free_bytes = &stats->psram_free;
        largest = &stats->psram_largest;
    } else {
        free_bytes = &stats->internal_free;
        largest = &stats->internal_largest;
        result = strdup(resp.text);
    }
    llm_response_free(&resp);

    if (!result && timed_out) {
        result = strdup(LLM_TIMEOUT_MSG);
    }

    return strip_tool_call_markup(result);
}

/* ── Extracted: dispatch response to outbound bus ─────────── */

static void dispatch_response(const agent_msg_t* msg,
    char* final_text)
{
    if (final_text && final_text[0]) {
        session_append(msg->chat_id, "user", msg->content);
        session_append(msg->chat_id, "assistant", final_text);

        agent_msg_t out = { 0 };
        strncpy(out.channel, msg->channel,
            sizeof(out.channel) - 1);
        strncpy(out.chat_id, msg->chat_id,
            sizeof(out.chat_id) - 1);
        out.content = final_text;
        if (message_bus_push_outbound(&out) != OK) {
            free(final_text);
        } else {
            syslog(LOG_INFO, "[ASK-DIAG] outbound\n");
        }
    } else {
        free(final_text);
        agent_msg_t out = { 0 };
        strncpy(out.channel, msg->channel,
            sizeof(out.channel) - 1);
        strncpy(out.chat_id, msg->chat_id,
            sizeof(out.chat_id) - 1);
        out.content = strdup("Sorry, I encountered an error.");
        if (out.content) {
            if (message_bus_push_outbound(&out) != OK) {
                free(out.content);
            }
        }
    }
}

