1231	/* Run the ReAct tool-calling loop. Returns final_text (caller owns). */
1232	static char* run_react_loop(const char* sys_prompt, cJSON* messages,
1233	    const char* tools_json, char* tool_output, size_t tool_size,
1234	    const agent_msg_t* msg)
1235	{
1236	    char prev_sig[512];
1237	    int dup_count;
1238	    char prev_name[64];
1239	    int name_repeat;
1240	    int iteration;
1241	    char* final_text = NULL;
1242	
1243	    prev_sig[0] = '\0';
1244	    dup_count = 0;
1245	    prev_name[0] = '\0';
1246	    name_repeat = 0;
1247	    int last_total_tokens = 0;
1248	    bool watchdog_fired = false;
1249	
1250	    /* Router: select and apply best backend before first LLM call.
1251	     * Estimate complexity from the last user message. */
1252	    llm_complexity_t complexity = LLM_COMPLEXITY_SIMPLE;
1253	    if (msg->content) {
1254	        complexity = llm_router_estimate_complexity(
1255	            msg->content, strlen(msg->content));
1256	    }
1257	    syslog(LOG_INFO, "[LLM-GATE] 1 router_enter\n");
1258	    int router_idx = llm_router_select(complexity);
1259	    syslog(LOG_INFO, "[LLM-GATE] 2 backend_selected idx=%d\n", router_idx);
1260	    if (router_idx >= 0) {
1261	        llm_router_apply(router_idx);
1262	    }
1263	
1264	    /* Structured trace: begin */
1265	    agent_trace_t trace;
1266	    agent_trace_begin(&trace, msg->chat_id, msg->channel);
1267	    trace.backend_idx = router_idx;
1268	
1269	    /* Cache check: for simple queries, try cache before LLM call */
1270	    if (msg->content && complexity == LLM_COMPLEXITY_SIMPLE) {
1271	        char* cached = llm_cache_get(msg->content, strlen(msg->content));
1272	        if (cached) {
1273	            syslog(LOG_INFO, "[%s] Cache hit, skipping LLM call\n", TAG);
1274	            final_text = cached;
1275	            agent_trace_step(&trace, 0, NULL, 0, 1);
1276	            agent_trace_end(&trace, AGENT_TRACE_OK);
1277	            goto send_reply;
1278	        }
1279	    }
1280	
1281	    for (iteration = 0; iteration < AGENT_AI_AGENT_MAX_TOOL_ITER;
1282	         iteration++) {
1283	        send_working_status(msg, iteration);
1284	
1285	        llm_response_t resp;
1286	        struct timeval tv_start, tv_end;
1287	        gettimeofday(&tv_start, NULL);
1288	        int err = agent_loop_llm_chat_tools(sys_prompt, messages, tools_json, &resp);
1289	        gettimeofday(&tv_end, NULL);
1290	        uint32_t latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
1291	
1292	        /* Router failover: on LLM call failure, try next backend */
1293	        if (err != OK && router_idx >= 0) {
1294	            syslog(LOG_WARNING,
1295	                "[%s] LLM call failed on backend %d, trying failover\n",
1296	                TAG, router_idx);
1297	            llm_router_report_failure(router_idx);
1298	
1299	            int next_idx = llm_router_select(complexity);
1300	            if (next_idx >= 0 && next_idx != router_idx) {
1301	                llm_router_apply(next_idx);
1302	                router_idx = next_idx;
1303	                trace.backend_idx = next_idx;
1304	                llm_response_free(&resp);
1305	                gettimeofday(&tv_start, NULL);
1306	                err = agent_loop_llm_chat_tools(sys_prompt, messages,
1307	                    tools_json, &resp);
1308	                gettimeofday(&tv_end, NULL);
1309	                latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
1310	            }
1311	        }
1312	
1313	        if (err != OK) {
1314	            /* Distinguish timeout-induced failure from other errors */
1315	            if (llm_call_timed_out(latency_ms)) {
1316	                syslog(LOG_WARNING,
1317	                    "[%s] LLM watchdog: call failed after %" PRIu32 " ms "
1318	                    "(limit %ds)\n",
1319	                    TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
1320	                agent_trace_step(&trace, iteration, NULL,
1321	                    latency_ms, 0);
1322	                llm_response_free(&resp);
1323	                final_text = strdup(LLM_TIMEOUT_MSG);
1324	                watchdog_fired = true;
1325	                break;
1326	            }
1327	            syslog(LOG_ERR, "[%s] LLM call failed (iter %d)\n",
1328	                TAG, iteration);
1329	            agent_trace_step(&trace, iteration, NULL, latency_ms, 0);
1330	            llm_response_free(&resp);
1331	            break;
1332	        }
1333	
1334	        /* Watchdog: if the LLM call took longer than the configured
1335	         * timeout, treat it as a timeout even if it returned OK.
1336	         * The socket SO_RCVTIMEO may have fired and caused a partial
1337	         * or error response that llm_chat_tools mapped to ERROR above,
1338	         * but if the call barely completed, we still flag it. */
1339	        if (llm_call_timed_out(latency_ms)) {
1340	            syslog(LOG_WARNING,
1341	                "[%s] LLM watchdog: call took %" PRIu32 " ms (limit %ds), "
1342	                "treating as timeout\n",
1343	                TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
1344	            agent_trace_step(&trace, iteration, NULL, latency_ms, 0);
1345	            llm_response_free(&resp);
1346	            final_text = strdup(LLM_TIMEOUT_MSG);
1347	            watchdog_fired = true;
1348	            break;
1349	        }
1350	
1351	        /* Report success to router */
1352	        if (router_idx >= 0) {
1353	            llm_router_report_success(router_idx);
1354	            llm_router_report_latency(router_idx, latency_ms);
1355	            if (resp.total_tokens > 0) {
1356	                llm_router_report_tokens(router_idx,
1357	                    resp.prompt_tokens, resp.completion_tokens);
1358	                last_total_tokens = resp.total_tokens;
1359	            }
1360	        }
1361	
1362	        syslog(LOG_INFO,
1363	            "[%s] LLM resp: text=%zu, tool_use=%d, calls=%d\n",
1364	            TAG, resp.text_len, resp.tool_use, resp.call_count);
1365	
1366	        if (!resp.tool_use) {
1367	            /* Cascade routing: if AUTO profile selected a cheap backend
1368	             * for a SIMPLE query but the response looks inadequate,
1369	             * retry once with PREMIUM tier. */
1370	            bool cascade_retry = false;
1371	            if (llm_router_get_profile() == LLM_ROUTE_AUTO
1372	                && complexity == LLM_COMPLEXITY_SIMPLE
1373	                && router_idx >= 0
1374	                && resp.text != NULL) {
1375	                bool low_quality = (strstr(resp.text, "I don't know") != NULL
1376	                    || strstr(resp.text, "I cannot") != NULL
1377	                    || strstr(resp.text, "无法") != NULL);
1378	                if (low_quality) {
1379	                    cascade_retry = true;
1380	                }
1381	            }
1382	
1383	            if (cascade_retry) {
1384	                syslog(LOG_INFO,
1385	                    "[%s] Cascade: cheap response inadequate, "
1386	                    "retrying with PREMIUM\n",
1387	                    TAG);
1388	
1389	                /* Save the cheap response as fallback before freeing */
1390	                char* fallback_text = NULL;
1391	                if (resp.text && resp.text_len > 0) {
1392	                    fallback_text = strdup(resp.text);
1393	                }
1394	                llm_response_free(&resp);
1395	
1396	                /* Select a PREMIUM backend without changing profile */
1397	                int prem_idx = llm_router_select_with_profile(
1398	                    LLM_COMPLEXITY_MEDIUM, LLM_ROUTE_PREMIUM);
1399	
1400	                if (prem_idx >= 0 && prem_idx != router_idx) {
1401	                    llm_router_apply(prem_idx);
1402	                    router_idx = prem_idx;
1403	                    trace.backend_idx = prem_idx;
1404	
1405	                    gettimeofday(&tv_start, NULL);
1406	                    err = agent_loop_llm_chat_tools(sys_prompt, messages,
1407	                        tools_json, &resp);
1408	                    gettimeofday(&tv_end, NULL);
1409	                    latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
1410	
1411	                    /* Watchdog check on cascade retry */
1412	                    if (llm_call_timed_out(latency_ms)) {
1413	                        syslog(LOG_WARNING,
1414	                            "[%s] LLM watchdog: cascade retry "
1415	                            "took %" PRIu32 " ms\n",
1416	                            TAG, latency_ms);
1417	                        free(fallback_text);
1418	                        fallback_text = NULL;
1419	                        final_text = strdup(LLM_TIMEOUT_MSG);
1420	                        watchdog_fired = true;
1421	                        agent_trace_step(&trace, iteration, NULL,
1422	                            latency_ms, 0);
1423	                        llm_response_free(&resp);
1424	                        break;
1425	                    }
1426	
1427	                    if (err == OK && resp.text && resp.text_len > 0) {
1428	                        final_text = strdup(resp.text);
1429	                        free(fallback_text);
1430	                        fallback_text = NULL;
1431	                    } else {
1432	                        /* Premium failed — fall back to cheap response */
1433	                        final_text = fallback_text;
1434	                        fallback_text = NULL;
1435	                    }
1436	                    agent_trace_step(&trace, iteration, NULL,
1437	                        latency_ms, err == OK);
1438	                    llm_response_free(&resp);
1439	                    break;
1440	                }
1441	                /* No premium backend available — use cheap response */
1442	                final_text = fallback_text;
1443	                fallback_text = NULL;
1444	                agent_trace_step(&trace, iteration, NULL, latency_ms, 1);
1445	                break;
1446	            }
1447	
1448	            if (resp.text && resp.text_len > 0 && !final_text) {
1449	                final_text = strdup(resp.text);
1450	            }
1451	            agent_trace_step(&trace, iteration, NULL, latency_ms, 1);
1452	            llm_response_free(&resp);
1453	            break;
1454	        }
1455	
1456	        syslog(LOG_INFO, "[%s] Tool iter %d: %d calls\n",
1457	            TAG, iteration + 1, resp.call_count);
1458	
1459	        /* Trace: log tool step */
1460	        agent_trace_step(&trace, iteration,
1461	            resp.call_count > 0 ? resp.calls[0].name : NULL,
1462	            latency_ms, 1);
1463	
1464	        /* Duplicate detection — break if stuck in a loop */
1465	        bool should_break = check_tool_dup(
1466	            &resp, prev_sig, &dup_count, prev_name, &name_repeat);
1467	
1468	        if (should_break) {
1469	            add_assistant_message(messages, &resp);
1470	            add_tool_result_messages(messages, &resp, tool_output,
1471	                tool_size, msg->channel, msg->chat_id);
1472	            llm_response_free(&resp);
1473	            break;
1474	        }
1475	
1476	        add_assistant_message(messages, &resp);
1477	        add_tool_result_messages(messages, &resp, tool_output,
1478	            tool_size, msg->channel, msg->chat_id);
1479	
1480	        /* Local tool shortcut: if the single tool in this round is a
1481	         * local file op, skip the next LLM round and use the tool
1482	         * output directly as the reply. Saves ~2s.
1483	         * Restricted to call_count == 1: the parallel path does not
1484	         * write into tool_output, so multi-call rounds must go through
1485	         * the LLM to aggregate results (and tool_output would be stale
1486	         * from a prior iteration if we allowed call_count > 1 here). */
1487	        if (resp.call_count == 1) {
1488	            bool all_local = true;
1489	            for (int i = 0; i < resp.call_count; i++) {
1490	                if (strcmp(resp.calls[i].name, "read_file") != 0
1491	                    && strcmp(resp.calls[i].name, "write_file") != 0
1492	                    && strcmp(resp.calls[i].name, "edit_file") != 0
1493	                    && strcmp(resp.calls[i].name, "list_dir") != 0) {
1494	                    all_local = false;
1495	                    break;
 800	            snprintf(nc, strlen(msg->content) + 64,
 801	                "请翻译以下内容（中英互译）：%s", msg->content + 11);
 802	            free(msg->content);
 803	            msg->content = nc;
 804	        }
 805	    } else if (strncmp(msg->content, "/daily", 6) == 0) {
 806	        char* nc = strdup(
 807	            "请给我一份今日简报，包括：当前时间、今日天气、"
 808	            "最新新闻摘要。");
 809	        if (nc) {
 810	            free(msg->content);
 811	            msg->content = nc;
 812	        }
 813	    }
 814	
 815	    if (reply) {
 816	        s_fast_path_count++;
 817	    }
 818	    return reply;
 819	}
