 822	static char* handle_slash_note(const agent_msg_t* msg)
 823	{
 824	    const char* note = msg->content + 6;
 825	    time_t now = time(NULL);
 826	    struct tm tm_now;
 827	    time_t local_epoch = now + 8 * 3600;
 828	
 829	    gmtime_r(&local_epoch, &tm_now);
 830	
 831	    char date_str[16];
 832	    strftime(date_str, sizeof(date_str), "%Y-%m-%d", &tm_now);
 833	    char time_str[16];
 834	    strftime(time_str, sizeof(time_str), "%H:%M", &tm_now);
 835	
 836	    char path[256];
 837	    snprintf(path, sizeof(path), "%s/memory/daily/%s.md",
 838	        AGENT_DATA_DIR, date_str);
 839	
 840	    char input[4096];
 841	    snprintf(input, sizeof(input),
 842	        "{\"path\":\"%s\",\"content\":\"%s %s\\n- %s %s\\n\"}",
 843	        path, "# ", date_str, time_str, note);
 844	
 845	    char* reply = calloc(1, 512);
 846	    if (reply) {
 847	        tool_registry_execute("write_file", input, reply, 512);
 848	        snprintf(reply, 512, "已记录：%s", note);
 849	    }
 850	    return reply;
 851	}
