 924	/* ── Extracted: strip leaked tool-call XML markup ─────────── */
 925	
 926	static char* strip_tool_call_markup(char* text)
 927	{
 928	    if (!text) {
 929	        return NULL;
 930	    }
 931	
 932	    int dirty = 0;
 933	    if (strstr(text, "<tool_call>") || strstr(text, ":tool_call>")) {
 934	        dirty = 1;
 935	    }
 936	    if (!dirty) {
 937	        return text;
 938	    }
 939	
 940	    syslog(LOG_WARNING,
 941	        "[%s] Force-finish text contains tool-call markup, stripping\n",
 942	        TAG);
 943	
 944	    size_t len = strlen(text);
 945	    char* clean = calloc(1, len + 1);
 946	    if (!clean) {
 947	        return text;
 948	    }
 949	
 950	    const char* r = text;
 951	    char* w = clean;
 952	
 953	    while (*r) {
 954	        const char* ts = NULL;
 955	        const char* te = NULL;
 956	
 957	        const char* plain = strstr(r, "<tool_call>");
 958	        const char* ns = strstr(r, ":tool_call>");
 959	        const char* ns_open = NULL;
 960	
 961	        if (ns) {
 962	            ns_open = ns;
 963	            while (ns_open > r && *(ns_open - 1) != '<') {
 964	                ns_open--;
 965	            }
 966	            if (ns_open > r) {
 967	                ns_open--;
 968	            } else {
 969	                ns_open = NULL;
 970	            }
 971	        }
 972	
 973	        if (plain && (!ns_open || plain <= ns_open)) {
 974	            ts = plain;
 975	            te = strstr(ts + 11, "</tool_call>");
 976	            if (te) {
 977	                te += 12;
 978	            }
 979	        } else if (ns_open) {
 980	            ts = ns_open;
 981	            size_t plen = (size_t)(ns - (ts + 1));
 982	            if (plen > 0 && plen < 32) {
 983	                char ctag[64];
 984	                snprintf(ctag, sizeof(ctag), "</%.*s:tool_call>",
 985	                    (int)plen, ts + 1);
 986	                te = strstr(ts, ctag);
 987	                if (te) {
 988	                    te += strlen(ctag);
 989	                }
 990	            }
 991	        }
 992	
 993	        if (ts && te) {
 994	            size_t prefix = (size_t)(ts - r);
 995	            memcpy(w, r, prefix);
 996	            w += prefix;
 997	            r = te;
 998	        } else {
 999	            size_t rest = strlen(r);
1000	            memcpy(w, r, rest);
1001	            w += rest;
1002	            break;
1003	        }
1004	    }
1005	    *w = '\0';
1006	
1007	    free(text);
