  1709	/****************************************************************************
  1710	 * Name: i2s_check_mclkfrequency
  1711	 *
  1712	 * Description:
  1713	 *   Check if MCLK frequency is compatible with the current data width and
  1714	 *   bits/sample set. Master clock should be multiple of the sample rate and
  1715	 *   bclk at the same time.
  1716	 *
  1717	 * Input Parameters:
  1718	 *   priv - Initialized I2S device structure.
  1719	 *
  1720	 * Returned Value:
  1721	 *   Returns the current master clock or a negated errno value on failure.
  1722	 *
  1723	 ****************************************************************************/
  1724	
  1725	static int32_t i2s_check_mclkfrequency(struct esp32s3_i2s_s *priv)
  1726	{
  1727	  uint32_t mclk_freq;
  1728	  uint32_t mclk_multiple = priv->mclk_multiple;

  1720	 * Returned Value:
  1721	 *   Returns the current master clock or a negated errno value on failure.
  1722	 *
  1723	 ****************************************************************************/
  1724	
  1725	static int32_t i2s_check_mclkfrequency(struct esp32s3_i2s_s *priv)
  1726	{
  1727	  uint32_t mclk_freq;
  1728	  uint32_t mclk_multiple = priv->mclk_multiple;
  1729	  uint32_t bclk = priv->rate * priv->config->total_slot * priv->data_width;
  1730	  int i;
  1731	
  1732	  /* If the master clock is divisible by both the sample rate and the bit
  1733	   * clock, everything is as expected and we can return the current master
  1734	   * clock frequency.
  1735	   */
  1736	
  1737	  if (priv->mclk_freq % priv->rate == 0 && priv->mclk_freq % bclk == 0)
  1738	    {
  1739	      priv->mclk_multiple = priv->mclk_freq / priv->rate;
  1740	      return priv->mclk_freq;
  1741	    }
  1742	
  1743	  /* Select the lowest multiplier for setting the master clock */
  1744	
  1745	  for (mclk_multiple = I2S_MCLK_MULTIPLE_128;
  1746	       mclk_multiple <= I2S_MCLK_MULTIPLE_512;
  1747	       mclk_multiple += I2S_MCLK_MULTIPLE_128)
  1748	    {
  1749	      mclk_freq = priv->rate * mclk_multiple;
  1750	      if (mclk_freq % priv->rate == 0 && mclk_freq % bclk == 0)
  1751	        {
  1752	          priv->mclk_multiple = mclk_multiple;
  1753	          i2s_setmclkfrequency((struct i2s_dev_s *)priv, mclk_freq);
  1754	          return priv->mclk_freq;
  1755	        }
  1756	    }
  1757	
  1758	  return -EINVAL;
  1759	}
