1126	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
1127	
1128	  if (bits != CONTEST_I2S_WIDTH)
1129	    {
1130	      return 0;
1131	    }
1132	
1133	  priv->data_width = bits;
1134	  contest_i2s_set_format(priv);
1135	  contest_i2s_set_rate(priv);
1136	  return bits;
1137	}
