1139	static int contest_i2s_receive(FAR struct i2s_dev_s *dev,
1140	                               FAR struct ap_buffer_s *apb,
1141	                               i2s_callback_t callback, FAR void *arg,
1142	                               uint32_t timeout)
1143	{
1144	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
1145	  FAR struct contest_i2s_rx_xfer_s *xfer = NULL;
1146	  irqstate_t flags;
1147	  size_t logical_bytes;
1148	  size_t logical_samples;
1149	  size_t raw_bytes;
1150	  uint32_t queued;
1151	  unsigned int i;
1152	
1153	  (void)timeout;
1154	
1155	  if (apb == NULL || callback == NULL || apb->samp == NULL)
1156	    {
1157	      return -EINVAL;
1158	    }
1159	
1160	  logical_bytes = apb->nmaxbytes - apb->curbyte;
1161	  logical_bytes -= logical_bytes % sizeof(int16_t);
1162	  logical_samples = logical_bytes / sizeof(int16_t);
1163	  raw_bytes = logical_samples * sizeof(uint32_t);
1164	  if (logical_bytes == 0 || raw_bytes > CONTEST_I2S_RX_RAW_MAX_BYTES)
1165	    {
1166	      return -EINVAL;
1167	    }
1168	
1169	  apb_reference(apb);
1170	
1171	  /* Reserve a free transaction while the descriptor is built outside the
1172	   * spinlock.  active and pending each retain independent raw DMA storage.
1173	   */
1174	
1175	  flags = spin_lock_irqsave(&priv->lock);
1176	  if (!priv->streaming || priv->reserved || priv->pending != NULL)
1177	    {
1178	      spin_unlock_irqrestore(&priv->lock, flags);
1179	      apb_free(apb);
1180	      return -EBUSY;
1181	    }
1182	
1183	  for (i = 0; i < CONTEST_I2S_RX_XFER_COUNT; i++)
1184	    {
1185	      if (!priv->xfer[i].in_use)
1186	        {
1187	          xfer = &priv->xfer[i];
1188	          xfer->in_use = true;
1189	          xfer->dma_diag = !priv->dma_diag_armed;
1190	          priv->dma_diag_armed = true;
1191	          break;
1192	        }
1193	    }
1194	
1195	  if (xfer == NULL)
1196	    {
1197	      spin_unlock_irqrestore(&priv->lock, flags);
1198	      apb_free(apb);
1199	      return -EBUSY;
1200	    }
1201	
1202	  priv->reserved = true;
1203	  spin_unlock_irqrestore(&priv->lock, flags);
1204	
1205	  xfer->next = NULL;
1206	  xfer->apb = apb;
1207	  xfer->callback = callback;
1208	  xfer->arg = arg;
1209	  xfer->logical_bytes = logical_bytes;
1210	  xfer->raw_bytes = raw_bytes;
1211	  xfer->queued_bytes = 0;
1212	  xfer->result = -EINPROGRESS;
1213	  if (xfer->dma_diag)
1214	    {
1215	      for (i = 0; i < logical_samples; i++)
1216	        {
1217	          xfer->raw[i] = CONTEST_I2S_RX_DMA_SENTINEL;
1218	        }
1219	
1220	      up_clean_dcache((uintptr_t)xfer->raw,
1221	                      (uintptr_t)xfer->raw + raw_bytes);
1222	    }
1223	
1224	  queued = contest_i2s_dma_setup_rx(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
1225	                                     (FAR uint8_t *)xfer->raw, raw_bytes);
1226	  xfer->queued_bytes = queued;
1227	  if (queued != raw_bytes)
1228	    {
1229	      flags = spin_lock_irqsave(&priv->lock);
1230	      priv->reserved = false;
1231	      xfer->in_use = false;
1232	      spin_unlock_irqrestore(&priv->lock, flags);
1233	      apb_free(apb);
1234	      return -ENOMEM;
1235	    }
1236	
1237	  /* Publish before hardware can complete.  The first transaction becomes
1238	   * active; the second becomes pending and is started by the EOF ISR.
1239	   */
1240	
1241	  flags = spin_lock_irqsave(&priv->lock);
1242	  if (!priv->streaming)
1243	    {
1244	      priv->reserved = false;
1245	      xfer->in_use = false;
1246	      spin_unlock_irqrestore(&priv->lock, flags);
1247	      apb_free(apb);
1248	      return -ECANCELED;
1249	    }
1250	
1251	  priv->reserved = false;
1252	  if (priv->active == NULL)
1253	    {
1254	      if (priv->started_once && priv->idle)
1255	        {
1256	          priv->underrun_count++;
1257	        }
1258	
1259	      priv->active = xfer;
1260	      contest_i2s_rx_start_active(priv);
1261	    }
1262	  else
1263	    {
1264	      priv->pending = xfer;
1265	    }
1266	
1267	  spin_unlock_irqrestore(&priv->lock, flags);
1268	
1269	  if (priv->eof_count < 2)
1270	    {
1271	      uint32_t eof_reg = getreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT));
1272	
1273	      syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", logical_bytes);
1274	      syslog(LOG_INFO, "[C-I2S] raw bytes=%zu logical bytes=%zu\n",
1275	             raw_bytes, logical_bytes);
1276	      syslog(LOG_INFO,
1277	             "[C-I2S] rx dma start raw=%zu eof_arg=%lu eof_reg=%08lx\n",
1278	             raw_bytes,
1279	             (unsigned long)contest_i2s_rx_eof_value(raw_bytes),
1280	             (unsigned long)eof_reg);
1281	    }
1282	
1283	  return OK;
1284	}
1285	
1286	static int contest_i2s_ioctl(FAR struct i2s_dev_s *dev, int cmd,
1287	                             unsigned long arg)
1288	{
1289	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
1290	  FAR struct contest_i2s_rx_xfer_s *xfer;
1291	  irqstate_t flags;
1292	  bool schedule = false;
1293	
1294	  (void)arg;
1295	
1296	  switch (cmd)
1297	    {
1298	      case AUDIOIOC_START:
1299	        flags = spin_lock_irqsave(&priv->lock);
1300	        priv->streaming = true;
1301	        priv->eof_count = 0;
1302	        priv->chained_count = 0;
1303	        priv->underrun_count = 0;
1304	        priv->started_once = false;
1305	        priv->idle = false;
1306	        priv->raw_logged = false;
1307	        priv->raw_diag_words = 0;
1308	        priv->dma_diag_armed = !priv->diagnostics_enabled;
1309	        memset(&priv->dma_diag, 0, sizeof(priv->dma_diag));
1310	        spin_unlock_irqrestore(&priv->lock, flags);
1311	        return OK;
1312	
1313	      case AUDIOIOC_STOP:
1314	        flags = spin_lock_irqsave(&priv->lock);
1315	        priv->streaming = false;
1316	        contest_i2s_stop_hw(priv);
1317	        if (priv->active != NULL)
1318	          {
1319	            xfer = priv->active;
1320	            xfer->result = -ECANCELED;
1321	            contest_i2s_rx_done_push(priv, xfer);
1322	            priv->active = NULL;
1323	            schedule = true;
1324	          }
1325	
1326	        if (priv->pending != NULL)
1327	          {
1328	            xfer = priv->pending;
1329	            xfer->result = -ECANCELED;
1330	            contest_i2s_rx_done_push(priv, xfer);
1331	            priv->pending = NULL;
1332	            schedule = true;
1333	          }
1334	
1335	        priv->idle = false;
1336	        spin_unlock_irqrestore(&priv->lock, flags);
1337	        syslog(LOG_INFO, "[C-I2S] rx eof=%lu chained=%lu underrun=%lu\n",
1338	               (unsigned long)priv->eof_count,
1339	               (unsigned long)priv->chained_count,
1340	               (unsigned long)priv->underrun_count);
1341	        if (priv->diagnostics_enabled)
1342	          {
1343	            if (priv->raw_logged)
1344	              {
1345	                contest_i2s_log_raw_diagnostics(priv->raw_diag,
1346	                                                 priv->raw_diag_words);
1347	              }
1348	            else
1349	              {
1350	                syslog(LOG_INFO,
1351	                       "[C-I2S] raw stride diagnostics: no signal chunk\n");
1352	              }
1353	
1354	            contest_i2s_log_rx_dma_diag(&priv->dma_diag);
1355	          }
1356	        if (schedule && work_available(&priv->rx_work))
1357	          {
1358	            work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker,
1359	                       priv, 0);
1360	          }
1361	
1362	        return OK;
1363	
1364	      default:
1365	        return -ENOTTY;
1366	    }
1367	}
