1369	static void contest_i2s_tx_stop_hw(FAR struct contest_i2s_tx_s *priv)
1370	{
1371	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_START, 0);
1372	  esp32s3_dma_disable(priv->dma_channel, true);
1373	  CLR_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
1374	                   DMA_OUT_TOTAL_EOF_CH0_INT_ENA |
1375	                   DMA_OUT_DSCR_ERR_CH0_INT_ENA);

1370	{
1371	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_START, 0);
1372	  esp32s3_dma_disable(priv->dma_channel, true);
1373	  CLR_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
1374	                   DMA_OUT_TOTAL_EOF_CH0_INT_ENA |
1375	                   DMA_OUT_DSCR_ERR_CH0_INT_ENA);
1376	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
1377	}
