1395	static void contest_i2s_tx_start_active(FAR struct contest_i2s_tx_s *priv)
1396	{
1397	  FAR struct contest_i2s_xfer_s *xfer = priv->active;
1398	
1399	  DEBUGASSERT(xfer != NULL);
1400	
1401	  /* This follows the reference driver's interrupt-safe next-DMA sequence.
1402	   * It does not reset the FIFO or clear I2S_TX_START between normal EOFs.
1403	   */
1404	
1405	  CLR_GDMA_CH_BITS(DMA_OUT_CONF1_CH0_REG, priv->dma_channel,
1406	                   DMA_OUT_CHECK_OWNER_CH0);
1407	  esp32s3_dma_load(xfer->desc, priv->dma_channel, true);
1408	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
1409	  SET_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
1410	                   DMA_OUT_TOTAL_EOF_CH0_INT_ENA |
1411	                   DMA_OUT_DSCR_ERR_CH0_INT_ENA);
1412	  esp32s3_dma_enable(priv->dma_channel, true);
1413	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_START);
1414	  priv->started_once = true;
1415	  priv->idle = false;
1416	}
