1418	static void contest_i2s_tx_capture_state(FAR struct contest_i2s_tx_s *priv,
1419	                                         FAR struct contest_i2s_xfer_s *xfer)
1420	{
1421	  unsigned int last = 0;
1422	
1423	  if (xfer != NULL)
1424	    {
1425	      while (last + 1 < CONTEST_I2S_DMA_DESC_COUNT &&
1426	             xfer->desc[last].next != NULL)
1427	        {
1428	          last++;
1429	        }
1430	    }
1431	
1432	  priv->timeout_ena = GET_GDMA_CH_REG(DMA_OUT_INT_ENA_CH0_REG,
1433	                                       priv->dma_channel);
1434	  priv->timeout_raw = GET_GDMA_CH_REG(DMA_OUT_INT_RAW_CH0_REG,
1435	                                       priv->dma_channel);
1436	  priv->timeout_status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG,
1437	                                          priv->dma_channel);
1438	  priv->timeout_link = GET_GDMA_CH_REG(DMA_OUT_LINK_CH0_REG,
1439	                                        priv->dma_channel);
1440	  priv->timeout_conf = getreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT));
1441	
1442	  if (xfer != NULL)
1443	    {
1444	      priv->timeout_desc_ctrl = xfer->desc[last].ctrl;
1445	      priv->timeout_desc_addr = xfer->desc[last].pbuf;
1446	    }
1447	}
