1480	static void contest_i2s_tx_set_rate(FAR struct contest_i2s_tx_s *priv)
1481	{
1482	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
1483	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
1484	  uint32_t freq_diff = CONTEST_I2S_SOURCE_CLOCK % mclk;
1485	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS * priv->data_width;
1486	  uint32_t bclk_div = mclk / bclk;
1487	  uint32_t numerator = 0;
1488	  uint32_t denominator = 1;
1489	  uint32_t regval;
1490	  uint32_t a;
1491	
1492	  /* This is the CLK160 fractional-divider procedure used by the reference
1493	   * ESP32-S3 I2S lower-half.  At 24 kHz it resolves to 26 + 1/24.
1494	   */
1495	
1496	  if (freq_diff != 0)
1497	    {
1498	      for (a = 2; a <= 63; a++)
1499	        {
1500	          uint32_t b = (freq_diff * a + mclk / 2) / mclk;
1501	
1502	          if (b != 0 && freq_diff * a == mclk * b)
1503	            {
1504	              numerator = b;
1505	              denominator = a;
1506	              break;
1507	            }
1508	        }
1509	    }
1510	
1511	  regval = getreg32(I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
1512	  regval &= ~I2S_TX_CLKM_DIV_NUM_M;
1513	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_NUM, mclk_div);
1514	  putreg32(regval, I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
1515	
1516	  regval = getreg32(I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
1517	  regval &= ~(I2S_TX_CLKM_DIV_Z_M | I2S_TX_CLKM_DIV_Y_M |
1518	              I2S_TX_CLKM_DIV_X_M | I2S_TX_CLKM_DIV_YN1_M);
1519	  if (numerator != 0)
1520	    {
1521	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Z, numerator);
1522	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y, denominator % numerator);
1523	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X,
1524	                               denominator / numerator - 1);
1525	    }
1526	
1527	  putreg32(regval, I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
1528	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_BCK_DIV_NUM_M,
1529	              FIELD_TO_VALUE(I2S_TX_BCK_DIV_NUM, bclk_div - 1));
1530	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_UPDATE);
1531	}
