1533	static void contest_i2s_tx_set_channels(
1534	  FAR struct contest_i2s_tx_s *priv)
1535	{
1536	  uint32_t channels_mask;
1537	
1538	  /* Keep two physical slots on the wire, but let the hardware consume one
1539	   * DMA word per WS frame and duplicate it to both slots in mono mode. */
1540	
1541	  modifyreg32(I2S_TX_TDM_CTRL_REG(CONTEST_I2S_TX_PORT),
1542	              I2S_TX_TDM_TOT_CHAN_NUM_M,
1543	              FIELD_TO_VALUE(I2S_TX_TDM_TOT_CHAN_NUM, 1));
1544	
1545	  channels_mask = getreg32(I2S_TX_TDM_CTRL_REG(CONTEST_I2S_TX_PORT));
1546	  channels_mask &= 0xffff0000;
1547	
1548	  if (priv->channels == 1)
1549	    {
1550	      modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
1551	                  I2S_TX_MONO_M, I2S_TX_MONO);
1552	      modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
1553	                  I2S_TX_CHAN_EQUAL_M, I2S_TX_CHAN_EQUAL);
1554	      channels_mask |= I2S_TX_TDM_CHAN0_EN;
1555	    }
1556	  else
1557	    {
1558	      modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
1559	                  I2S_TX_MONO_M, 0);
1560	      modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
1561	                  I2S_TX_CHAN_EQUAL_M, 0);
1562	      channels_mask |= I2S_TX_TDM_CHAN0_EN | I2S_TX_TDM_CHAN1_EN;
1563	    }
1564	
1565	  putreg32(channels_mask, I2S_TX_TDM_CTRL_REG(CONTEST_I2S_TX_PORT));
1566	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_UPDATE);
1567	}
