1615	static void contest_i2s_tx_worker(FAR void *arg)
1616	{
1617	  FAR struct contest_i2s_tx_s *priv = arg;
1618	  FAR struct contest_i2s_xfer_s *xfer;
1619	  FAR struct ap_buffer_s *apb;
1620	  i2s_callback_t callback;
1621	  FAR void *callback_arg;
1622	  uint32_t irq_status;
1623	  int result;
1624	  irqstate_t flags;
1625	
1626	  for (;;)
1627	    {
1628	      flags = spin_lock_irqsave(&priv->lock);
1629	      xfer = priv->done_head;
1630	      if (xfer != NULL)
1631	        {
1632	          priv->done_head = xfer->next;
1633	          if (priv->done_head == NULL)
1634	            {
1635	              priv->done_tail = NULL;
1636	            }
1637	
1638	          xfer->next = NULL;
1639	          xfer->in_use = false;
1640	        }
1641	
1642	      irq_status = priv->irq_status;
1643	      spin_unlock_irqrestore(&priv->lock, flags);
1644	
1645	      if (xfer == NULL)
1646	        {
1647	          return;
1648	        }
1649	
1650	      /* Release the lower-half transaction slot before the callback.  The
1651	       * upper half may submit the replacement buffer from this callback.
1652	       */
1653	
1654	      apb = xfer->apb;
1655	      callback = xfer->callback;
1656	      callback_arg = xfer->arg;
1657	      result = xfer->result;
1658	
1659	      if (priv->eof_count <= 3 || result < 0)
1660	        {
1661	          syslog(LOG_INFO, "[C-I2S] tx irq status=%08lx\n",
1662	                 (unsigned long)irq_status);
1663	          syslog(LOG_INFO, "[C-I2S] tx worker bytes=%zu\n", xfer->nbytes);
1664	          syslog(LOG_INFO, "[C-I2S] tx callback\n");
1665	        }
1666	      callback(&priv->dev, apb, callback_arg, result);
1667	      apb_free(apb);
1668	    }
1669	}
