1671	static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
1672	{
1673	  FAR struct contest_i2s_tx_s *priv = arg;
1674	  uint32_t status;
1675	  irqstate_t flags;
1676	
1677	  (void)irq;
1678	  (void)context;
1679	
1680	  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
1681	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
1682	
1683	  if ((status & (DMA_OUT_TOTAL_EOF_CH0_INT_ST |
1684	                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
1685	    {
1686	      return OK;
1687	    }
1688	
1689	  flags = spin_lock_irqsave(&priv->lock);
1690	  if (priv->active != NULL)
1691	    {
1692	      priv->irq_status = status;
1693	      if ((status & DMA_OUT_TOTAL_EOF_CH0_INT_ST) != 0)
1694	        {
1695	          priv->active->result = OK;
1696	          contest_i2s_tx_done_push(priv, priv->active);
1697	          priv->active = priv->pending;
1698	          priv->pending = NULL;
1699	          priv->eof_count++;
1700	
1701	          if (priv->active != NULL && priv->streaming)
1702	            {
1703	              contest_i2s_tx_start_active(priv);
1704	              priv->chained_count++;
1705	              if (priv->eof_count <= 3)
1706	                {
1707	                  syslog(LOG_INFO, "[C-I2S] tx eof=%lu chained\n",
1708	                         (unsigned long)priv->eof_count);
1709	                }
1710	            }
1711	          else
1712	            {
1713	              /* Leave I2S clocks running until AUDIOIOC_STOP.  A new
1714	               * submission records an underrun only when it resumes this
1715	               * previously idle stream; the final drain is not an error.
1716	               */
1717	
1718	              priv->idle = true;
1719	            }
1720	        }
1721	      else
1722	        {
1723	          priv->active->result = -EIO;
1724	          contest_i2s_tx_done_push(priv, priv->active);
1725	          priv->active = NULL;
1726	          if (priv->pending != NULL)
1727	            {
1728	              priv->pending->result = -ECANCELED;
1729	              contest_i2s_tx_done_push(priv, priv->pending);
1730	              priv->pending = NULL;
1731	            }
1732	
1733	          priv->streaming = false;
1734	          contest_i2s_tx_stop_hw(priv);
1735	        }
1736	
1737	      if (work_available(&priv->tx_work))
1738	        {
1739	          work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv,
1740	                     0);
1741	        }
1742	    }
1743	
1744	  spin_unlock_irqrestore(&priv->lock, flags);
1745	  return OK;
1746	}
