 40	 ****************************************************************************/
 41	
 42	static void checkcorruption_handler(FAR struct mm_allocnode_s *node,
 43	                                    FAR void *arg)
 44	{
 45	  size_t nodesize = MM_SIZEOF_NODE(node);
 46	
 47	  if (MM_NODE_IS_ALLOC(node))
 48	    {
 49	      ASSERT(nodesize >= MM_SIZEOF_ALLOCNODE);
 50	    }
 51	  else
 52	    {
 53	      FAR struct mm_freenode_s *fnode = (FAR void *)node;
 54	
 55	      ASSERT(nodesize >= MM_MIN_CHUNK);
 56	      ASSERT(fnode->blink->flink == fnode);
 57	      ASSERT(MM_SIZEOF_NODE(fnode->blink) <= nodesize);
 58	      ASSERT(fnode->flink == NULL ||
 59	             fnode->flink->blink == fnode);
 60	      ASSERT(fnode->flink == NULL ||
 61	             MM_SIZEOF_NODE(fnode->flink) == 0 ||
 62	             MM_SIZEOF_NODE(fnode->flink) >= nodesize);
 63	    }
 64	}
