 68	 ****************************************************************************/
 69	
 70	/****************************************************************************
 71	 * Name: mm_checkcorruption
 72	 *
 73	 * Description:
 74	 *   mm_checkcorruption is used to check whether memory heap is normal.
 75	 *
 76	 ****************************************************************************/
 77	
 78	void mm_checkcorruption(FAR struct mm_heap_s *heap)
 79	{
 80	  if (!up_interrupt_context())
 81	    {
 82	      mm_free_delaylist(heap);
 83	    }
 84	
 85	  mm_foreach(heap, checkcorruption_handler, NULL);
 86	}
