 44	/****************************************************************************
 45	 * Name: mm_foreach
 46	 *
 47	 * Description:
 48	 *   Visit each node to run handler in heap.
 49	 *
 50	 ****************************************************************************/
 51	
 52	void mm_foreach(FAR struct mm_heap_s *heap, mm_node_handler_t handler,
 53	                FAR void *arg)
 54	{
 55	  FAR struct mm_allocnode_s *node;
 56	  FAR struct mm_allocnode_s *prev;
 57	  size_t nodesize;
 58	  bool bypass;
 59	  bool locked = false;
 60	#if CONFIG_MM_REGIONS > 1
 61	  int region;
 62	#else
 63	#  define region 0
 64	#endif
 65	
 66	  DEBUGASSERT(handler);
 67	
 68	  /* Visit each region */
 69	
 70	#if CONFIG_MM_REGIONS > 1
 71	  for (region = 0; region < heap->mm_nregions; region++)
 72	#endif
 73	    {
 74	      prev = NULL;
 75	
 76	      /* Visit each node in the region
 77	       * Retake the mutex for each region to reduce latencies
 78	       */
 79	
 80	#if defined(CONFIG_BUILD_FLAT) || defined(__KERNEL__)
 81	      if (up_interrupt_context())
 82	        {
 83	#ifdef CONFIG_SMP
 84	          return;
 85	#else
 86	          if (nxrmutex_is_locked(&heap->mm_lock))
 87	            {
 88	              return;
 89	            }
 90	#endif
 91	        }
 92	      else
 93	        {
 94	          DEBUGASSERT(!sched_idletask());
 95	          DEBUGVERIFY(nxrmutex_lock(&heap->mm_lock));
 96	          locked = true;
 97	        }
 98	#else
 99	      /* User space in kernel build cannot check interrupt context */
100	
101	      DEBUGVERIFY(nxrmutex_lock(&heap->mm_lock));
102	      locked = true;
103	#endif
104	
105	      bypass = kasan_bypass(true);
106	
107	      for (node = heap->mm_heapstart[region];
108	           node < heap->mm_heapend[region];
109	           node = (FAR struct mm_allocnode_s *)((FAR char *)node + nodesize))
110	        {
111	          nodesize = MM_SIZEOF_NODE(node);
112	          DEBUGASSERT(nodesize >= MM_SIZEOF_ALLOCNODE);
113	          minfo("region=%d node=%p size=%zu preceding=%u (%c %c)\n",
114	                region, node, nodesize, (unsigned int)node->preceding,
115	                MM_PREVNODE_IS_FREE(node) ? 'F' : 'A',
116	                MM_NODE_IS_ALLOC(node) ? 'A' : 'F');
117	
118	          handler(node, arg);
119	
120	          DEBUGASSERT(MM_PREVNODE_IS_ALLOC(node) ||
121	                      MM_SIZEOF_NODE(prev) == node->preceding);
122	          prev = node;
123	        }
124	
125	      minfo("region=%d node=%p heapend=%p\n",
250	  /* Mutex for controlling access to this heap */
251	
252	  rmutex_t mm_lock;
253	
254	  /* This is the size of the heap provided to mm */
255	
256	  size_t mm_heapsize;
257	
258	  /* This is the heap maximum used memory size */
259	
260	  size_t mm_maxused;
261	
262	  /* This is the current used size of the heap */
263	
264	  size_t mm_curused;
265	
266	  /* The first and last allocated nodes of each region */
267	
268	  FAR struct mm_allocnode_s *mm_heapstart[CONFIG_MM_REGIONS];
269	  FAR struct mm_allocnode_s *mm_heapend[CONFIG_MM_REGIONS];
270	  size_t mm_regionsize[CONFIG_MM_REGIONS];
271	
272	#if CONFIG_MM_REGIONS > 1
273	  int mm_nregions;
274	#endif
275	
276	  /* All free nodes are maintained in a doubly linked list.  This
277	   * array provides some hooks into the list at various points to
278	   * speed up searching of free nodes.
279	   */
280	
281	  struct mm_freenode_s mm_nodelist[MM_NNODES];
282	
283	  /* Free delay list, as sometimes we can't do free immdiately. */
284	
285	  mm_delaylist_t delay;
286	
287	  /* The is a multiple mempool of the heap */
288	
289	#ifdef CONFIG_MM_HEAP_MEMPOOL
290	  size_t                         mm_threshold;
291	  FAR struct mempool_multiple_s *mm_mpool;
292	#endif
293	
294	#if defined(CONFIG_FS_PROCFS) && !defined(CONFIG_FS_PROCFS_EXCLUDE_MEMINFO)
295	  FAR struct procfs_meminfo_entry_s *mm_procfs;
296	#endif
297	
298	  /* Kasan is disable or enable for this heap */
299	
300	  bool mm_nokasan;
301	};
