 89	static bool agent_heap_gate_is_sentinel(const struct mm_heap_s *heap,
 90	    const struct mm_freenode_s *ptr)
 91	{
 92	    for (int i = 0; i < MM_NNODES; i++) {
 93	        if (ptr == &heap->mm_nodelist[i]) {
 94	            return true;
 95	        }
 96	    }
 97	
 98	    return false;
 99	}
