101	static bool agent_heap_gate_is_region_node(const struct mm_heap_s *heap,
102	    const struct mm_freenode_s *ptr)
103	{
104	    uintptr_t address = (uintptr_t)ptr;
105	
106	    if (ptr == NULL || (address & (MM_ALIGN - 1)) != 0) {
107	        return false;
108	    }
109	
110	#if CONFIG_MM_REGIONS > 1
111	    int regions = heap->mm_nregions;
112	#else
113	    int regions = 1;
114	#endif
115	
116	    if (regions <= 0 || regions > CONFIG_MM_REGIONS) {
117	        return false;
118	    }
119	
120	    for (int i = 0; i < regions; i++) {
121	        uintptr_t start = (uintptr_t)heap->mm_heapstart[i];
122	        uintptr_t end = (uintptr_t)heap->mm_heapend[i];
123	
124	        if (end > start && end - start >= sizeof(struct mm_freenode_s) &&
125	            address >= start && address < end &&
126	            address <= end - sizeof(struct mm_freenode_s)) {
127	            return true;
128	        }
129	    }
130	
131	    return false;
132	}
