134	static bool agent_heap_gate_is_safe_link(const struct mm_heap_s *heap,
135	    const struct mm_freenode_s *ptr)
136	{
137	    return ptr == NULL || agent_heap_gate_is_sentinel(heap, ptr) ||
138	        agent_heap_gate_is_region_node(heap, ptr);
139	}
