142	 * performs no allocation and never emits diagnostics while the lock is held.
143	 */
144	static bool agent_heap_gate_check(struct agent_heap_gate_result_s *result)
145	{
146	    struct mm_heap_s *heap = USR_HEAP;
147	    int regions;
148	
149	    memset(result, 0, sizeof(*result));
150	    result->reason = AGENT_HEAP_GATE_NONE;
151	
152	    if (heap == NULL || up_interrupt_context() || sched_idletask()) {
153	        result->reason = AGENT_HEAP_GATE_CONTEXT;
154	        return false;
155	    }
156	
157	#if CONFIG_MM_REGIONS > 1
158	    regions = heap->mm_nregions;
159	#else
160	    regions = 1;
161	#endif
162	
163	    if (regions <= 0 || regions > CONFIG_MM_REGIONS) {
164	        result->reason = AGENT_HEAP_GATE_REGION;
165	        return false;
166	    }
167	
168	    if (nxrmutex_lock(&heap->mm_lock) < 0) {
169	        result->reason = AGENT_HEAP_GATE_LOCK;
170	        return false;
171	    }
172	
173	    for (int region = 0; region < regions; region++) {
174	        uintptr_t start = (uintptr_t)heap->mm_heapstart[region];
175	        uintptr_t end = (uintptr_t)heap->mm_heapend[region];
176	        struct mm_allocnode_s *node;
177	        size_t previous_size = 0;
178	
179	        if (start == 0 || end <= start ||
180	            end - start < 2 * MM_SIZEOF_ALLOCNODE) {
181	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_REGION, region,
182	                NULL, 0);
183	            goto done;
184	        }
185	
186	        node = heap->mm_heapstart[region];
187	        while ((uintptr_t)node < end) {
188	            uintptr_t address = (uintptr_t)node;
189	            size_t remaining = end - address;
190	            size_t size;
191	
192	            if (remaining < MM_SIZEOF_ALLOCNODE ||
193	                (address & (MM_ALIGN - 1)) != 0) {
194	                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE, region,
195	                    (struct mm_freenode_s *)node, 0);
196	                goto done;
197	            }
198	
199	            size = MM_SIZEOF_NODE(node);
200	            if (size < MM_SIZEOF_ALLOCNODE ||
201	                (size & (MM_ALIGN - 1)) != 0 ||
202	                size > remaining) {
203	                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE, region,
204	                    (struct mm_freenode_s *)node, size);
205	                goto done;
206	            }
207	
208	            if (address != start && node->preceding != previous_size) {
209	                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE, region,
210	                    (struct mm_freenode_s *)node, size);
211	                goto done;
212	            }
213	
214	            if (MM_NODE_IS_FREE(node)) {
215	                struct mm_freenode_s *free_node =
216	                    (struct mm_freenode_s *)node;
217	
218	                if (size < MM_MIN_CHUNK) {
219	                    agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE, region,
220	                        free_node, size);
221	                    goto done;
222	                }
223	
224	                if (!agent_heap_gate_is_safe_link(heap, free_node->blink) ||
225	                    !agent_heap_gate_is_safe_link(heap, free_node->flink)) {
226	                    agent_heap_gate_capture_links(result, free_node);
227	                    agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, region,
228	                        free_node, size);
229	                    goto done;
230	                }
231	
232	                if (free_node->blink != NULL &&
233	                    ((agent_heap_gate_is_sentinel(heap, free_node->blink) &&
234	                      free_node->blink->flink != free_node) ||
235	                     (!agent_heap_gate_is_sentinel(heap, free_node->blink) &&
236	                      ((struct mm_freenode_s *)free_node->blink)->flink !=
237	                          free_node))) {
238	                    agent_heap_gate_capture_links(result, free_node);
239	                    agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, region,
240	                        free_node, size);
241	                    goto done;
242	                }
243	
244	                if (free_node->flink != NULL &&
245	                    ((agent_heap_gate_is_sentinel(heap, free_node->flink) &&
246	                      free_node->flink->blink != free_node) ||
247	                     (!agent_heap_gate_is_sentinel(heap, free_node->flink) &&
248	                      ((struct mm_freenode_s *)free_node->flink)->blink !=
249	                          free_node))) {
250	                    agent_heap_gate_capture_links(result, free_node);
251	                    agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, region,
252	                        free_node, size);
253	                    goto done;
254	                }
255	            }
256	
257	            previous_size = size;
258	            node = (struct mm_allocnode_s *)(address + size);
259	        }
260	
261	        if ((uintptr_t)node != end ||
262	            MM_SIZEOF_NODE(node) != MM_SIZEOF_ALLOCNODE ||
263	            !MM_NODE_IS_ALLOC(node) || node->preceding != previous_size) {
264	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE, region,
265	                (struct mm_freenode_s *)node, MM_SIZEOF_NODE(node));
266	            goto done;
267	        }
268	    }
269	
270	    for (int i = 0; i < MM_NNODES; i++) {
271	        struct mm_freenode_s *sentinel = &heap->mm_nodelist[i];
272	
273	        if (!agent_heap_gate_is_safe_link(heap, sentinel->flink) ||
274	            !agent_heap_gate_is_safe_link(heap, sentinel->blink)) {
275	            agent_heap_gate_capture_links(result, sentinel);
276	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
277	                sentinel, 0);
278	            goto done;
279	        }
280	
281	        if (sentinel->flink != NULL && sentinel->flink->blink != sentinel) {
282	            agent_heap_gate_capture_links(result, sentinel);
283	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
284	                sentinel, 0);
285	            goto done;
286	        }
287	
288	        if (sentinel->blink != NULL && sentinel->blink->flink != sentinel) {
289	            agent_heap_gate_capture_links(result, sentinel);
290	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
291	                sentinel, 0);
292	            goto done;
293	        }
294	    }
295	
296	done:
297	    nxrmutex_unlock(&heap->mm_lock);
298	    return result->reason == AGENT_HEAP_GATE_NONE;
299	}
