   167	/* ── Backend management ───────────────────────────────────── */
   168	
   169	int llm_router_set_backend(int index, const llm_backend_t* backend)
   170	{
   171	    if (index < 0 || index >= LLM_ROUTER_MAX_BACKENDS || !backend) {
   172	        return -1;
   173	    }
   174	
   175	    pthread_mutex_lock(&s_router_lock);
   176	    memcpy(&s_backends[index], backend, sizeof(llm_backend_t));
   177	    s_backends[index].fail_count = 0;
   178	
   179	    /* Save to config */
   180	    cJSON* obj = cJSON_CreateObject();
   181	    if (!obj) {
   182	        pthread_mutex_unlock(&s_router_lock);
   183	        return -1;
   184	    }
   185	    cJSON_AddStringToObject(obj, "host", backend->host);
   186	    cJSON_AddStringToObject(obj, "path", backend->path);
   187	    cJSON_AddStringToObject(obj, "port", backend->port);
   188	    cJSON_AddStringToObject(obj, "api_key", backend->api_key);
   189	    cJSON_AddStringToObject(obj, "model", backend->model);
   190	    cJSON_AddNumberToObject(obj, "priority", backend->priority);
   191	    cJSON_AddNumberToObject(obj, "cost_tier", backend->cost_tier);
   192	
   193	    char* json = cJSON_PrintUnformatted(obj);
   194	    cJSON_Delete(obj);
   195	    obj = NULL;
   196	
   197	    if (json) {
   198	        char key[64];
   199	        snprintf(key, sizeof(key), "%s%d", CFG_KEY_BACKEND_PREFIX, index);
   200	        claw_config_set(key, json);
   201	        free(json);
   202	        json = NULL;
   203	    }
   204	
   205	    if (index >= s_backend_count) {
   206	        s_backend_count = index + 1;
   207	    }
   208	
   209	    pthread_mutex_unlock(&s_router_lock);
   210	
   211	    syslog(LOG_INFO, "[%s] Backend %d configured: %s\n", TAG, index, backend->host);
   212	    return 0;
   213	}
