   322	/* Direct path via vela_tls */
   323	static int llm_http_direct(const char* post_data, resp_buf_t* rb,
   324	    int* out_status)
   325	{
   326	    /* Snapshot config under lock */
   327	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
   328	    pthread_mutex_lock(&s_llm_lock);
   329	    memcpy(api_key, s_api_key, sizeof(api_key));
   330	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
   331	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
   332	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
   333	    memcpy(model, s_model, sizeof(model));
   334	    pthread_mutex_unlock(&s_llm_lock);
   335	
   336	    /* Allocate the response buffer once and hand it directly to the
   337	     * TLS layer.  Previously we allocated a separate raw_buf and then
   338	     * copied into resp_buf — doubling peak memory usage.  Now the
   339	     * resp_buf IS the raw buffer, eliminating the copy. */
   340	    size_t raw_cap = AGENT_LLM_STREAM_BUF_SIZE;
   341	    if (resp_buf_init(rb, raw_cap) != OK)
   342	        return ERROR;
   343	
   344	    /* OpenAI-compatible format: Authorization: Bearer <key> */
   345	    char auth_header[256];
   346	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
   347	
   348	    /* Extract provider ID from model string (e.g. "xiaomi/mimo-claw-0301" →
   349	     * "xiaomi") Mify gateway requires X-Model-Provider-Id header for routing. */
   350	    char provider[64] = { 0 };
   351	    const char* slash = strchr(model, '/');
   352	    if (slash) {
   353	        size_t plen = (size_t)(slash - model);
   354	        if (plen >= sizeof(provider))
   355	            plen = sizeof(provider) - 1;
   356	        memcpy(provider, model, plen);
   357	    }
   358	
   359	    vela_header_t hdrs[] = { { "Authorization", auth_header },
   360	        { provider[0] ? "X-Model-Provider-Id" : NULL,
   361	            provider[0] ? provider : NULL },
   362	        { NULL, NULL } };
   363	
   364	    int status;
   365	    int use_tls = (strcmp(llm_port, "443") == 0);
   366	
   367	    if (use_tls) {
   368	        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
   369	            rb->data, raw_cap);
   370	    } else {
   371	        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
   372	            rb->data, raw_cap);
   373	    }
   374	
   375	    if (status < 0) {
   470	        body += 4;
   471	        size_t blen = rb->len - (size_t)(body - rb->data);
   472	        memmove(rb->data, body, blen);
   473	        rb->len = blen;
   474	        rb->data[rb->len] = '\0';
   475	    }
   476	
   477	    return OK;
   478	}
   479	
   480	int llm_http_call(const char* post_data, resp_buf_t* rb,
   481	    int* out_status)
   482	{
   483	    /* For plain HTTP endpoints (port != 443), always use direct path.
   484	     * The proxy does CONNECT + TLS which fails on non-TLS endpoints.
   485	     * Non-TLS HTTP endpoints (port != 443) are reachable
   486	     * directly without a proxy anyway. */
   487	    int use_tls;
   488	    pthread_mutex_lock(&s_llm_lock);
   489	    use_tls = (strcmp(s_llm_port, "443") == 0);
   490	    pthread_mutex_unlock(&s_llm_lock);
   491	
   492	#ifdef CONFIG_AI_AGENT_NET_RPMSG
   493	    int retry_max = network_get_retry_max();
   494	    int retry_base = network_get_retry_base_sec();
   495	    int ret = ERROR;
   496	
   497	    for (int attempt = 0; attempt <= retry_max; attempt++) {
   498	        if (attempt > 0) {
   499	            /* Check network state before retrying */
   500	            if (network_get_state() != NET_STATE_CONNECTED) {
   501	                syslog(LOG_WARNING, "[llm] Network down, skip retry %d\n", attempt);
   502	                break;
   503	            }
   504	            int delay = retry_base * (1 << (attempt - 1));
   505	            syslog(LOG_INFO, "[llm] Retry %d/%d after %ds\n", attempt, retry_max, delay);
   506	            sleep(delay);
   507	        }
   508	
   509	        if (use_tls && http_proxy_is_enabled()) {
   510	            ret = llm_http_via_proxy(post_data, rb, out_status);
   511	        } else {
   512	            ret = llm_http_direct(post_data, rb, out_status);
   513	        }
   514	
   515	        if (ret == OK) {
   516	            return OK;
   517	        }
   518	
   519	        syslog(LOG_WARNING, "[llm] HTTP call failed (attempt %d/%d)\n",
   520	            attempt + 1, retry_max + 1);
   521	    }
   522	
   523	    /* All retries failed — notify user */
   524	    syslog(LOG_ERR, "[llm] All %d retries failed\n", retry_max + 1);
   525	    {
   526	        agent_msg_t notify;
   527	        memset(&notify, 0, sizeof(notify));
   528	        strncpy(notify.channel, "cli", sizeof(notify.channel) - 1);
   529	        notify.content = strdup("网络请求失败，请检查蓝牙连接");
   530	        if (notify.content) {
   531	            if (message_bus_push_outbound(&notify) != OK) {
   532	                free(notify.content);
   533	            }
   534	        }
   535	    }
   536	    return ERROR;
   537	#else
   538	    if (use_tls && http_proxy_is_enabled())
   539	        return llm_http_via_proxy(post_data, rb, out_status);
   540	    return llm_http_direct(post_data, rb, out_status);
   541	#endif
   542	}
