   545	
   546	/* Extract text from OpenAI response format: choices[0].message.content */
   547	void extract_text(cJSON* root, char* buf, size_t size)
   548	{
   549	    buf[0] = '\0';
   550	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
   551	    if (!choices || !cJSON_IsArray(choices))
   552	        return;
   553	
   554	    cJSON* first = choices->child;
   555	    if (!first)
   556	        return;
   557	
   558	    cJSON* message = cJSON_GetObjectItem(first, "message");
   559	    if (!message)
   560	        return;
   561	
   562	    cJSON* content = cJSON_GetObjectItem(message, "content");
   563	    if (!content || !cJSON_IsString(content))
   564	        return;
   565	
   566	    size_t tlen = strlen(content->valuestring);
   567	    size_t copy = (tlen < size - 1) ? tlen : size - 1;
   568	    memcpy(buf, content->valuestring, copy);
   569	    buf[copy] = '\0';
   570	}
