   572	/* ── Public: simple chat ──────────────────────────────────── */
   573	
   574	int llm_chat(const char* system_prompt, const char* messages_json,
   575	    char* response_buf, size_t buf_size)
   576	{
   577	    /* Snapshot config under lock */
   578	    char model[64], api_key[128], llm_host[128];
   579	    pthread_mutex_lock(&s_llm_lock);
   580	    memcpy(model, s_model, sizeof(model));
   581	    memcpy(api_key, s_api_key, sizeof(api_key));
   582	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
   583	    pthread_mutex_unlock(&s_llm_lock);
   584	
   585	    if (api_key[0] == '\0') {
   586	        snprintf(response_buf, buf_size, "Error: No API key configured");
   587	        return ERROR;
   588	    }
   589	
   590	    cJSON* body = cJSON_CreateObject();
   591	    cJSON_AddStringToObject(body, "model",
   592	        model_name_for_api(model, llm_host));
   593	
   594	    if (is_openai_compat_host(llm_host))
   595	        cJSON_AddNumberToObject(body, "max_completion_tokens",
   596	            AGENT_LLM_MAX_TOKENS_OPENAI);
   597	    else
   598	        cJSON_AddNumberToObject(body, "max_tokens", AGENT_LLM_MAX_TOKENS);
   599	
   600	    cJSON* messages = cJSON_Parse(messages_json);
   601	    if (!messages)
   602	        messages = cJSON_CreateArray();
   603	
   604	    /* Prepend system message (OpenAI format) */
   605	    cJSON* sys_msg = cJSON_CreateObject();
   606	    cJSON_AddStringToObject(sys_msg, "role", "system");
   607	    cJSON_AddStringToObject(sys_msg, "content", system_prompt);
   608	    cJSON_InsertItemInArray(messages, 0, sys_msg);
   609	
   610	    cJSON_AddItemToObject(body, "messages", messages);
   611	
   612	    char* post_data = cJSON_PrintUnformatted(body);
   613	    cJSON_Delete(body);
   614	    if (!post_data) {
   615	        snprintf(response_buf, buf_size, "Error: Failed to build request");
   616	        return ERROR;
   617	    }
   618	
   619	    syslog(LOG_INFO, "[%s] Calling LLM API (model: %s, host: %s, %d bytes)\n",
   620	        TAG, model, llm_host, (int)strlen(post_data));
   621	
   622	    resp_buf_t rb = { 0 };
   623	    int status = 0;
