 58	void cmd_set_llm(int argc, char** argv)
 59	{
 60	    if (argc < 2) {
 61	        printf("Usage: set_llm <preset> [api_key]\n"
 62	               "       set_llm <url> <model> [api_key]\n"
 63	               "       set_llm <host> <model> [api_key]\n"
 64	               "\n"
 65	               "Presets:\n"
 66	               "  kimi     - api.moonshot.cn  (kimi-k2.5)\n"
 67	               "  qwen     - dashscope.aliyuncs.com  (qwen-turbo)\n"
 68	               "  deepseek - api.deepseek.com  (deepseek-chat)\n"
 69	               "  glm      - open.bigmodel.cn  (glm-4-flash)\n"
 70	               "  openai   - api.openai.com  (gpt-4o)\n"
 71	               "  openrouter - openrouter.ai  (openrouter/hunter-alpha)\n"
 72	               "  mimo     - api.xiaomimimo.com  (MiMo-v2-Flash)\n"
 73	               "\n"
 74	               "URL format (for custom endpoints):\n"
 75	               "  set_llm http://host:port/path model key\n"
 76	               "  set_llm http://<your-endpoint>/v1 model-name sk-xxx\n"
 77	               "\n"
 78	               "Note: set_llm writes to router slot 0 and applies immediately.\n");
 79	        return;
 80	    }
 81	
 82	    const char* arg1 = argv[1];
 83	
 84	    const char* host = NULL;
 85	    const char* port = "443";
 86	    const char* path = "/v1/chat/completions";
 87	    const char* model = NULL;
 88	    const char* api_key = NULL;
 89	    int cost_tier = 1;
 90	    static char parsed_host[128];
 91	
 92	    /* Check if arg1 is a URL (http:// or https://) */
 93	    if (strncmp(arg1, "http://", 7) == 0 || strncmp(arg1, "https://", 8) == 0) {
 94	        /* Parse URL: scheme://host[:port][/path] */
 95	        int is_https = (strncmp(arg1, "https://", 8) == 0);
 96	        const char* after_scheme = arg1 + (is_https ? 8 : 7);
 97	        port = is_https ? "443" : "80";
 98	
 99	        /* Find host end (first '/' or ':' or end) */
100	        const char* slash = strchr(after_scheme, '/');
101	        const char* colon = strchr(after_scheme, ':');
102	
103	        if (colon && (!slash || colon < slash)) {
104	            /* host:port/path */
105	            size_t hlen = (size_t)(colon - after_scheme);
106	            if (hlen >= sizeof(parsed_host))
107	                hlen = sizeof(parsed_host) - 1;
108	            memcpy(parsed_host, after_scheme, hlen);
109	            parsed_host[hlen] = '\0';
110	            host = parsed_host;
111	
112	            /* Extract port */
113	            static char parsed_port[8];
114	            const char* port_start = colon + 1;
115	            const char* port_end = slash ? slash : port_start + strlen(port_start);
116	            size_t plen = (size_t)(port_end - port_start);
117	            if (plen >= sizeof(parsed_port))
118	                plen = sizeof(parsed_port) - 1;
119	            memcpy(parsed_port, port_start, plen);
120	            parsed_port[plen] = '\0';
121	            port = parsed_port;
122	        } else if (slash) {
123	            /* host/path (no port) */
124	            size_t hlen = (size_t)(slash - after_scheme);
125	            if (hlen >= sizeof(parsed_host))
126	                hlen = sizeof(parsed_host) - 1;
127	            memcpy(parsed_host, after_scheme, hlen);
128	            parsed_host[hlen] = '\0';
129	            host = parsed_host;
130	        } else {
131	            /* host only */
132	            strncpy(parsed_host, after_scheme, sizeof(parsed_host) - 1);
133	            parsed_host[sizeof(parsed_host) - 1] = '\0';
134	            host = parsed_host;
135	        }
136	
137	        /* Extract path from URL */
138	        if (slash && slash[1]) {
139	            path = slash;
140	        } else {
141	            path = "/v1/chat/completions";
142	        }
143	
144	        /* Append /chat/completions if path is just /v1 */
145	        static char full_path[256];
146	        if (strcmp(path, "/v1") == 0 || strcmp(path, "/v1/") == 0) {
147	            snprintf(full_path, sizeof(full_path), "/v1/chat/completions");
148	            path = full_path;
149	        }
150	
151	        if (argc >= 3)
152	            model = argv[2];
153	        if (argc >= 4)
154	            api_key = argv[3];
155	    }
156	    /* Check presets - reuse g_router_presets table */
157	    else {
158	        const router_preset_t* preset = NULL;
159	        for (int i = 0; g_router_presets[i].name; i++) {
160	            if (strcmp(g_router_presets[i].name, arg1) == 0) {
161	                preset = &g_router_presets[i];
162	                break;
163	            }
164	        }
165	
166	        if (preset) {
167	            host = preset->host;
168	            path = preset->path;
169	            model = preset->model;
170	            cost_tier = preset->cost_tier;
171	            port = "443";
172	            if (argc >= 3)
173	                api_key = argv[2];
174	        } else {
175	            /* Custom: arg1 is bare host */
176	            host = arg1;
177	            port = "443";
178	            if (argc >= 3)
179	                model = argv[2];
180	            if (argc >= 4)
181	                api_key = argv[3];
182	        }
183	    }
184	
185	    /* Build backend and write to router slot 0 */
186	    llm_backend_t backend = { 0 };
187	    strncpy(backend.host, host, sizeof(backend.host) - 1);
188	    backend.host[sizeof(backend.host) - 1] = '\0';
189	    strncpy(backend.path, path, sizeof(backend.path) - 1);
190	    backend.path[sizeof(backend.path) - 1] = '\0';
191	    strncpy(backend.port, port, sizeof(backend.port) - 1);
192	    backend.port[sizeof(backend.port) - 1] = '\0';
193	    if (model) {
194	        strncpy(backend.model, model, sizeof(backend.model) - 1);
195	        backend.model[sizeof(backend.model) - 1] = '\0';
196	    }
197	
198	    /* Preserve existing API key if not provided */
199	    if (api_key) {
200	        strncpy(backend.api_key, api_key, sizeof(backend.api_key) - 1);
201	        backend.api_key[sizeof(backend.api_key) - 1] = '\0';
202	    } else {
203	        llm_backend_t old;
204	        if (llm_router_get_backend(0, &old) == 0 && old.api_key[0]) {
205	            strncpy(backend.api_key, old.api_key, sizeof(backend.api_key) - 1);
206	            backend.api_key[sizeof(backend.api_key) - 1] = '\0';
207	        }
208	    }
209	
210	    backend.priority = 0;
211	    backend.cost_tier = cost_tier;
212	    backend.enabled = true;
213	
214	    /* Write to router slot 0 and apply immediately.
215	     * llm_router_apply() -> llm_set_all() already persists
216	     * llm_host/llm_path/llm_port/api_key/model to config_store,
217	     * so config_show and reboot are covered without extra writes here. */
218	    llm_router_set_backend(0, &backend);
219	    llm_router_apply(0);
220	
221	    printf("LLM backend: %s:%s%s (model: %s) [router slot 0]\n",
222	        host, port, path, model ? model : "(unchanged)");
223	    if (api_key) {
224	        printf("API key saved.\n");
225	    }
318	static int router_select_internal(llm_complexity_t complexity,
319	    llm_route_profile_t profile)
320	{
321	    int best_idx = -1;
322	    int best_score = -1;
323	    int fallback_idx = -1;          /* least-backed-off backend */
324	    uint32_t fallback_until = UINT32_MAX;
325	    uint32_t now = (uint32_t)time(NULL);
326	
327	    for (int i = 0; i < LLM_ROUTER_MAX_BACKENDS; i++) {
328	        llm_backend_t* b = &s_backends[i];
329	
330	        /* Skip disabled or unconfigured backends */
331	        if (!b->enabled || b->host[0] == '\0') {
332	            continue;
333	        }
334	
335	        /* Skip backends in backoff period, but track the one
336	         * with the shortest remaining backoff as fallback. */
337	        if (b->backoff_until > now) {
338	            if (b->backoff_until < fallback_until) {
339	                fallback_until = b->backoff_until;
340	                fallback_idx = i;
341	            }
342	            continue;
343	        }
344	
345	        /* Auto-recovery: reset backends that have been disabled long enough */
346	        if (b->fail_count >= MAX_CONSECUTIVE_FAILURES) {
347	            if (now - b->last_fail_ts >= RECOVERY_INTERVAL_SEC) {
348	                syslog(LOG_INFO, "[%s] Auto-recovering backend %d after %ds\n",
349	                    TAG, i, RECOVERY_INTERVAL_SEC);
350	                b->fail_count = 0;
351	            } else {
352	                continue;
353	            }
354	        }
355	
356	        /* Calculate score based on profile and complexity */
357	        int score = 100 - b->priority * 10;
358	
359	        switch (profile) {
360	        case LLM_ROUTE_ECO:
361	            /* Prefer cheapest (lower cost_tier = higher score) */
362	            score += (3 - b->cost_tier) * 30;
363	            break;
364	
365	        case LLM_ROUTE_PREMIUM:
366	            /* Prefer best quality (higher cost_tier = higher score) */
367	            score += b->cost_tier * 30;
368	            break;
369	
370	        case LLM_ROUTE_AUTO:
371	        default:
372	            /* Balance: match cost_tier to complexity */
373	            if (complexity == LLM_COMPLEXITY_SIMPLE && b->cost_tier <= 1) {
374	                score += 20;
375	            } else if (complexity == LLM_COMPLEXITY_MEDIUM && b->cost_tier == 1) {
376	                score += 20;
377	            } else if (complexity == LLM_COMPLEXITY_COMPLEX && b->cost_tier >= 2) {
378	                score += 20;
379	            }
380	            break;
381	        }
382	
383	        /* Penalize backends with recent failures */
384	        score -= b->fail_count * 15;
385	
386	        /* Slight preference for lower-latency backends */
387	        if (b->avg_latency_ms > 0 && b->avg_latency_ms < 5000) {
388	            score += (5000 - (int)b->avg_latency_ms) / 500;
389	        }
390	
391	        if (score > best_score) {
392	            best_score = score;
393	            best_idx = i;
394	        }
395	    }
396	
397	    if (best_idx < 0) {
398	        /* All backends in backoff — use the one recovering soonest */
399	        best_idx = fallback_idx;
400	        if (best_idx >= 0) {
401	            syslog(LOG_INFO, "[%s] All backends backed off, using fallback %d\n",
402	                TAG, best_idx);
403	        } else {
404	            syslog(LOG_WARNING, "[%s] No available backend\n", TAG);
405	        }
406	    }
407	
408	    return best_idx;
409	}
