   137	/* ── Persistent connection pool (keep-alive) ─────────────────── */
   138	/* Keeps one live TLS connection per host:port so repeated calls to
   139	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
   140	
   141	#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
   142	#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
   143	#else
   144	#define CONN_POOL_SIZE 2
   145	#endif
   146	
   147	typedef struct {
   148	    tls_ctx_t ctx;
   149	    char host[128];
   150	    char port[8];
   151	    bool in_use; /* locked by a request */
   152	    bool valid; /* connection is alive */
   153	} conn_slot_t;
   154	
   155	static conn_slot_t s_pool[CONN_POOL_SIZE];
   156	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
   157	
   158	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
   159	static conn_slot_t* pool_acquire(const char* host, const char* port)
   160	{
   161	    pthread_mutex_lock(&s_pool_lock);
   162	
   163	    /* 1. Find an existing valid slot for this host:port */
   164	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
   165	        conn_slot_t* s = &s_pool[i];
   166	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
   167	            s->in_use = true;
   168	            pthread_mutex_unlock(&s_pool_lock);
   169	            return s;
   170	        }
   171	    }
   172	
   173	    /* 2. Find an empty slot */
   174	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
   175	        if (!s_pool[i].valid && !s_pool[i].in_use) {
   176	            s_pool[i].in_use = true;
   177	            pthread_mutex_unlock(&s_pool_lock);
   178	            return &s_pool[i];
   179	        }
   180	    }
   181	
   182	    /* 3. Evict the first non-in-use slot */
   183	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
   184	        if (!s_pool[i].in_use) {
   185	            tls_ctx_free(&s_pool[i].ctx);
   186	            s_pool[i].valid = false;
   187	            s_pool[i].in_use = true;
   188	            pthread_mutex_unlock(&s_pool_lock);
   189	            return &s_pool[i];
   190	        }
   191	    }
   192	
   193	    pthread_mutex_unlock(&s_pool_lock);
   194	    return NULL; /* all slots busy — caller falls back to ephemeral */
   195	}
   196	
   197	/* Return a slot to the pool.  keep=true means the connection is still alive. */
   198	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
   199	{
   200	    pthread_mutex_lock(&s_pool_lock);
   201	    if (keep) {
   202	        strncpy(s->host, host, sizeof(s->host) - 1);
   203	        strncpy(s->port, port, sizeof(s->port) - 1);
   204	        s->valid = true;
   205	    } else {
   206	        tls_ctx_free(&s->ctx);
   207	        s->valid = false;
   208	        s->host[0] = '\0';
   209	    }
   210	    s->in_use = false;
   211	    pthread_mutex_unlock(&s_pool_lock);
   212	}
