+            size_t guard_size = MM_SIZEOF_NODE(node);
+            bool guard_prev_free = MM_PREVNODE_IS_FREE(node);
+
+            if (guard_size != MM_SIZEOF_ALLOCNODE ||
+                !MM_NODE_IS_ALLOC(node)) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_GUARD, region,
+                    (struct mm_freenode_s *)node, guard_size);
+                goto done;
+            }
