+    AGENT_HEAP_GATE_FREELIST_BIN,
+    AGENT_HEAP_GATE_FREELIST_MEMBERSHIP,
+};
+
+struct agent_heap_gate_result_s
+{
+    enum agent_heap_gate_reason_e reason;
+    int region;
+    uintptr_t node;
+    uintptr_t flink;
+    uintptr_t blink;
+    size_t size;
+};
+
+static const char *agent_heap_gate_reason_name(
+    enum agent_heap_gate_reason_e reason)
+{
+    switch (reason) {
+    case AGENT_HEAP_GATE_NONE:
+        return "NONE";
+    case AGENT_HEAP_GATE_CONTEXT:
+        return "CONTEXT";
+    case AGENT_HEAP_GATE_LOCK:
+        return "LOCK";
+    case AGENT_HEAP_GATE_REGION:
+        return "REGION";
+    case AGENT_HEAP_GATE_NODE_ADDR:
+        return "NODE_ADDR";
+    case AGENT_HEAP_GATE_NODE_ALIGN:
+        return "NODE_ALIGN";
+    case AGENT_HEAP_GATE_NODE_SIZE:
+        return "NODE_SIZE";
+    case AGENT_HEAP_GATE_NODE_BOUNDS:
+        return "NODE_BOUNDS";
+    case AGENT_HEAP_GATE_PREVFREE_FLAG:
+        return "PREVFREE_FLAG";
+    case AGENT_HEAP_GATE_PRECEDING_SIZE:
+        return "PRECEDING_SIZE";
+    case AGENT_HEAP_GATE_FREE_MIN_SIZE:
+        return "FREE_MIN_SIZE";
+    case AGENT_HEAP_GATE_GUARD:
+        return "GUARD";
+    case AGENT_HEAP_GATE_LINK:
+        return "LINK";
+    case AGENT_HEAP_GATE_FREELIST_NODE:
+        return "FREELIST_NODE";
+    case AGENT_HEAP_GATE_FREELIST_CYCLE:
+        return "FREELIST_CYCLE";
+    case AGENT_HEAP_GATE_FREELIST_TERM:
+        return "FREELIST_TERM";
+    case AGENT_HEAP_GATE_FREELIST_BIN:
+        return "FREELIST_BIN";
+    case AGENT_HEAP_GATE_FREELIST_MEMBERSHIP:
+        return "FREELIST_MEMBERSHIP";
+    default:
+        return "UNKNOWN";
+    }
+}
+
+static void agent_heap_gate_fail(struct agent_heap_gate_result_s *result,
+    enum agent_heap_gate_reason_e reason, int region,
+    const struct mm_freenode_s *node, size_t size)
+{
+    result->reason = reason;
+    result->region = region;
+    result->node = (uintptr_t)node;
+    result->size = size;
+}
+
+static void agent_heap_gate_capture_links(
+    struct agent_heap_gate_result_s *result,
+    const struct mm_freenode_s *node)
+{
+    result->flink = (uintptr_t)node->flink;
+    result->blink = (uintptr_t)node->blink;
+}
+
+static int agent_heap_gate_sentinel_index(const struct mm_heap_s *heap,
+    const struct mm_freenode_s *ptr)
+{
+    int i;
+
+    for (i = 0; i < MM_NNODES; i++) {
+        if (ptr == &heap->mm_nodelist[i]) {
+            return i;
+        }
+    }
+
+    return -1;
+}
+
+#if CONFIG_MM_REGIONS > 1
+static int agent_heap_gate_region_count(const struct mm_heap_s *heap)
+{
+    return heap->mm_nregions;
+}
+#else
+static int agent_heap_gate_region_count(const struct mm_heap_s *heap)
+{
+    UNUSED(heap);
+    return 1;
+}
+#endif
+
+/* Find an exact physical node boundary. The physical walk has already
+ * validated the heap before this helper is used for a free-list pointer. */
+static bool agent_heap_gate_find_physical_node(
+    const struct mm_heap_s *heap, uintptr_t target,
+    bool *is_free, int *region_out, size_t *size_out)
+{
+    int regions = agent_heap_gate_region_count(heap);
+    int region;
+
+    if (target == 0 || (target & (MM_ALIGN - 1)) != 0 ||
+        regions <= 0 || regions > CONFIG_MM_REGIONS) {
+        return false;
+    }
+
+    for (region = 0; region < regions; region++) {
+        uintptr_t start = (uintptr_t)heap->mm_heapstart[region];
+        uintptr_t end = (uintptr_t)heap->mm_heapend[region];
+        uintptr_t address = start;
+
+        if (start == 0 || end <= start) {
+            return false;
+        }
+
+        while (address < end) {
+            size_t remaining = end - address;
+            struct mm_allocnode_s *node;
+            size_t size;
+
+            if (remaining < MM_SIZEOF_ALLOCNODE ||
+                (address & (MM_ALIGN - 1)) != 0) {
+                return false;
+            }
+
+            node = (struct mm_allocnode_s *)address;
+            size = MM_SIZEOF_NODE(node);
+            if (size < MM_SIZEOF_ALLOCNODE ||
+                (size & (MM_ALIGN - 1)) != 0 || size > remaining ||
+                size > UINTPTR_MAX - address) {
+                return false;
+            }
+
+            if (address == target) {
+                *is_free = MM_NODE_IS_FREE(node);
+                *region_out = region;
+                *size_out = size;
+                return true;
+            }
+
+            address += size;
+        }
+
+        if (address != end && target < end) {
+            return false;
+        }
+    }
+
+    return false;
+}
+
+static bool agent_heap_gate_is_valid_link(const struct mm_heap_s *heap,
+    const struct mm_freenode_s *ptr)
+{
+    bool is_free;
+    int region;
+    size_t size;
+
+    if (ptr == NULL || agent_heap_gate_sentinel_index(heap, ptr) >= 0) {
+        return true;
+    }
+
+    return agent_heap_gate_find_physical_node(heap, (uintptr_t)ptr,
+        &is_free, &region, &size) && is_free;
+}
+
+static bool agent_heap_gate_add_count(size_t *value)
+{
+    if (*value == SIZE_MAX) {
+        return false;
+    }
+

+
+    (*value)++;
+    return true;
+}
+
+static bool agent_heap_gate_physical_walk(struct mm_heap_s *heap,
+    struct agent_heap_gate_result_s *result, size_t *physical_nodes,
+    size_t *physical_free_nodes)
+{
+    int regions = agent_heap_gate_region_count(heap);
+    int region;
+
+    if (regions <= 0 || regions > CONFIG_MM_REGIONS) {
+        result->reason = AGENT_HEAP_GATE_REGION;
+        return false;
+    }
+
+    for (region = 0; region < regions; region++) {
+        uintptr_t start = (uintptr_t)heap->mm_heapstart[region];
+        uintptr_t end = (uintptr_t)heap->mm_heapend[region];
+        uintptr_t limit;
+        uintptr_t address = start;
+        size_t previous_size = 0;
+        bool previous_free = false;
+        bool have_previous = false;
+        size_t steps = 0;
+        size_t max_steps;
+
+        if (start == 0 || end <= start ||
+            end - start < MM_SIZEOF_ALLOCNODE ||
+            heap->mm_regionsize[region] > UINTPTR_MAX - start) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_REGION, region,
+                NULL, 0);
+            return false;
+        }
+
+        limit = start + heap->mm_regionsize[region];
+        if (limit < end || limit - end < MM_SIZEOF_ALLOCNODE ||
+            (start & (MM_ALIGN - 1)) != 0 ||
+            (end & (MM_ALIGN - 1)) != 0) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_REGION, region,
+                NULL, 0);
+            return false;
+        }
+
+        max_steps = (end - start) / MM_SIZEOF_ALLOCNODE;
+        if (max_steps == SIZE_MAX) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_BOUNDS,
+                region, NULL, 0);
+            return false;
+        }
+        max_steps++;
+
+        while (address < end) {
+            uintptr_t remaining = end - address;
+            struct mm_allocnode_s *node;
+            size_t size;
+            bool previous_free_flag;
+
+            if (steps >= max_steps) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_BOUNDS,
+                    region, (struct mm_freenode_s *)address, 0);
+                return false;
+            }
+            steps++;
+
+            if (remaining < MM_SIZEOF_ALLOCNODE ||
+                (address & (MM_ALIGN - 1)) != 0) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_ALIGN,
+                    region, (struct mm_freenode_s *)address, 0);
+                return false;
+            }
+
+            node = (struct mm_allocnode_s *)address;
+            size = MM_SIZEOF_NODE(node);
+            if (size < MM_SIZEOF_ALLOCNODE) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_SIZE,
+                    region, (struct mm_freenode_s *)node, size);
+                return false;
+            }
+            if ((size & (MM_ALIGN - 1)) != 0) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_ALIGN,
+                    region, (struct mm_freenode_s *)node, size);
+                return false;
+            }
+            if (size > remaining || size > UINTPTR_MAX - address) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_BOUNDS,
+                    region, (struct mm_freenode_s *)node, size);
+                return false;
+            }
+
+            previous_free_flag = MM_PREVNODE_IS_FREE(node);
+            if (have_previous && previous_free_flag != previous_free) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_PREVFREE_FLAG,
+                    region, (struct mm_freenode_s *)node, size);
+                return false;
+            }
+            if (have_previous && previous_free_flag &&
+                node->preceding != previous_size) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_PRECEDING_SIZE,
+                    region, (struct mm_freenode_s *)node, size);
+                return false;
+            }
+
+            if (!agent_heap_gate_add_count(physical_nodes)) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_BOUNDS,
+                    region, (struct mm_freenode_s *)node, size);
+                return false;
+            }
+            if (MM_NODE_IS_FREE(node)) {
+                if (size < MM_MIN_CHUNK ||
+                    !agent_heap_gate_add_count(physical_free_nodes)) {
+                    agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREE_MIN_SIZE,
+                        region, (struct mm_freenode_s *)node, size);
+                    return false;
+                }
+            }
+
+            previous_size = size;
+            previous_free = MM_NODE_IS_FREE(node);
+            have_previous = true;
+            address += size;
+        }
+
+        if (address != end || steps >= max_steps) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_BOUNDS,
+                region, (struct mm_freenode_s *)address, 0);
+            return false;
+        }
+
+        /* mm_heapend points at the allocated terminal guard. */
+        {
+            struct mm_allocnode_s *guard = (struct mm_allocnode_s *)end;
+            size_t guard_size = MM_SIZEOF_NODE(guard);
+            bool guard_previous_free = MM_PREVNODE_IS_FREE(guard);
+
+            if (guard_size != MM_SIZEOF_ALLOCNODE ||
+                !MM_NODE_IS_ALLOC(guard)) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_GUARD, region,
+                    (struct mm_freenode_s *)guard, guard_size);
+                return false;
+            }
+            if (!have_previous || guard_previous_free != previous_free) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_PREVFREE_FLAG,
+                    region, (struct mm_freenode_s *)guard, guard_size);
+                return false;
+            }
+            if (guard_previous_free && guard->preceding != previous_size) {
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_PRECEDING_SIZE,
+                    region, (struct mm_freenode_s *)guard, guard_size);
+                return false;
+            }
+        }
+    }
+
+    return true;
+}
+
+static bool agent_heap_gate_count_membership(const struct mm_heap_s *heap,
+    uintptr_t target, size_t max_steps, size_t *matches,
+    struct agent_heap_gate_result_s *result)
+{
+    struct mm_freenode_s *previous = &heap->mm_nodelist[0];
+    struct mm_freenode_s *current = previous->flink;
+    size_t steps = 0;
+
+    *matches = 0;
+    while (current != NULL) {
+        bool is_free;
+        int region;
+        size_t size;
+
+        if (steps >= max_steps) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_CYCLE,
+                -1, current, 0);
+            return false;
+        }
+        steps++;
+
+        if (agent_heap_gate_sentinel_index(heap, current) < 0 &&
+            (!agent_heap_gate_find_physical_node(heap, (uintptr_t)current,
+                &is_free, &region, &size) || !is_free)) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
+                -1, current, 0);
+            return false;
+        }
+
+        if ((uintptr_t)current == target) {
+            if (!agent_heap_gate_add_count(matches)) {
+                agent_heap_gate_fail(result,
+                    AGENT_HEAP_GATE_FREELIST_MEMBERSHIP, -1, current, size);
+                return false;
+            }
+        }
+
+        if ((uintptr_t)current->blink != (uintptr_t)previous) {
+            agent_heap_gate_capture_links(result, current);
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
+                current, 0);
+            return false;
+        }
+        if (!agent_heap_gate_is_valid_link(heap, current->flink)) {
+            agent_heap_gate_capture_links(result, current);
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE, -1,
+                current, 0);
+            return false;
+        }
+
+        previous = current;
+        current = current->flink;
+    }
+
+    return true;
+}
+
+static bool agent_heap_gate_check(struct agent_heap_gate_result_s *result)
+{
+    struct mm_heap_s *heap = USR_HEAP;
+    size_t physical_nodes = 0;
+    size_t physical_free_nodes = 0;
+    size_t list_nodes = 0;
+    size_t list_limit;
+    size_t steps = 0;
+    struct mm_freenode_s *previous;
+    struct mm_freenode_s *current;
+    int expected_sentinel = 1;
+    int current_bin = 0;
+
+    memset(result, 0, sizeof(*result));
+    result->reason = AGENT_HEAP_GATE_NONE;
+
+    if (heap == NULL || up_interrupt_context() || sched_idletask()) {
+        result->reason = AGENT_HEAP_GATE_CONTEXT;
+        return false;
+    }
+
+    if (nxrmutex_lock(&heap->mm_lock) < 0) {
+        result->reason = AGENT_HEAP_GATE_LOCK;
+        return false;
+    }
+

+
+    if (!agent_heap_gate_physical_walk(heap, result, &physical_nodes,
+        &physical_free_nodes)) {
+        goto done;
+    }
+
+    list_limit = physical_nodes;
+    if (list_limit > SIZE_MAX - MM_NNODES) {
+        list_limit = SIZE_MAX;
+    } else {
+        list_limit += MM_NNODES;
+        if (list_limit != SIZE_MAX) {
+            list_limit++;
+        }
+    }
+    if (list_limit == 0 || heap->mm_nodelist[0].blink != NULL) {
+        agent_heap_gate_capture_links(result, &heap->mm_nodelist[0]);
+        agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
+            &heap->mm_nodelist[0], 0);
+        goto done;
+    }
+
+    previous = &heap->mm_nodelist[0];
+    current = previous->flink;
+    while (current != NULL) {
+        int sentinel = agent_heap_gate_sentinel_index(heap, current);
+        bool is_free;
+        int region;
+        size_t size;
+
+        if (steps >= list_limit) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_CYCLE,
+                -1, current, 0);
+            goto done;
+        }
+        steps++;
+
+        if (sentinel >= 0) {
+            if (sentinel != expected_sentinel ||
+                expected_sentinel >= MM_NNODES) {
+                agent_heap_gate_capture_links(result, current);
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_TERM,
+                    -1, current, 0);
+                goto done;
+            }
+            current_bin = sentinel;
+            expected_sentinel++;
+        } else if (!agent_heap_gate_find_physical_node(heap,
+                       (uintptr_t)current, &is_free, &region, &size) ||
+                   !is_free) {
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
+                -1, current, 0);
+            goto done;
+        } else {
+            if (size < MM_MIN_CHUNK || mm_size2ndx(size) != current_bin) {
+                agent_heap_gate_capture_links(result, current);
+                agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_BIN,
+                    region, current, size);
+                goto done;
+            }
+            if (!agent_heap_gate_add_count(&list_nodes)) {
+                agent_heap_gate_fail(result,
+                    AGENT_HEAP_GATE_FREELIST_MEMBERSHIP, region,
+                    current, size);
+                goto done;
+            }
+        }
+
+        if ((uintptr_t)current->blink != (uintptr_t)previous) {
+            agent_heap_gate_capture_links(result, current);
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
+                current, 0);
+            goto done;
+        }
+        if (!agent_heap_gate_is_valid_link(heap, current->flink)) {
+            agent_heap_gate_capture_links(result, current);
+            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
+                -1, current, 0);
+            goto done;
+        }
+
+        previous = current;
+        current = current->flink;
+    }
+
+    if (expected_sentinel != MM_NNODES || list_nodes != physical_free_nodes) {
+        agent_heap_gate_fail(result,
+            expected_sentinel != MM_NNODES ? AGENT_HEAP_GATE_FREELIST_TERM :
+                                             AGENT_HEAP_GATE_FREELIST_MEMBERSHIP,
+            -1, previous, 0);
+        goto done;
+    }
+
+    /* Rescan the validated global chain for every physical free node. */
+    {
+        int regions = agent_heap_gate_region_count(heap);
+        int region;
+
+        for (region = 0; region < regions; region++) {
+            uintptr_t address = (uintptr_t)heap->mm_heapstart[region];
+            uintptr_t end = (uintptr_t)heap->mm_heapend[region];
+
+            while (address < end) {
+                struct mm_allocnode_s *node =
+                    (struct mm_allocnode_s *)address;
+                size_t size = MM_SIZEOF_NODE(node);
+
+                if (MM_NODE_IS_FREE(node)) {
+                    size_t matches;
+
+                    if (!agent_heap_gate_count_membership(heap, address,
+                        list_limit, &matches, result) || matches != 1) {
+                        agent_heap_gate_fail(result,
+                            AGENT_HEAP_GATE_FREELIST_MEMBERSHIP, region,
+                            (struct mm_freenode_s *)node, size);
+                        goto done;
+                    }
+                }
+                address += size;
+            }
+        }
+    }
+
+done:
+    nxrmutex_unlock(&heap->mm_lock);
+    return result->reason == AGENT_HEAP_GATE_NONE;
+}
+
+static bool agent_heap_gate_tools_parsed(void)
+{
+    struct agent_heap_gate_result_s result;
+    bool pass = agent_heap_gate_check(&result);
+
+    if (pass) {
+        syslog(LOG_INFO, "[HEAP-GATE] TOOLS_PARSED PASS\n");
+    } else {
+        syslog(LOG_ERR,
+            "[HEAP-GATE] TOOLS_PARSED FAIL reason=%s(%d) region=%d "
+            "node=%p flink=%p blink=%p size=%zu\n",
+            agent_heap_gate_reason_name(result.reason), result.reason,
+            result.region, (void *)result.node,
+            (void *)result.flink, (void *)result.blink, result.size);
+    }
+
+    return pass;
