174	uint32_t llm_cache_tokens_saved(void)
175	{
176	    uint32_t val;
177	    pthread_mutex_lock(&s_cache_lock);
178	    val = s_tokens_saved;
179	    pthread_mutex_unlock(&s_cache_lock);
180	    return val;
181	}
