183	uint32_t llm_cache_hit_count(void)
184	{
185	    uint32_t val;
186	    pthread_mutex_lock(&s_cache_lock);
187	    val = s_total_hits;
188	    pthread_mutex_unlock(&s_cache_lock);
189	    return val;
190	}
191	
192	void llm_cache_cleanup(void)
193	{
194	    pthread_mutex_lock(&s_cache_lock);
195	    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
196	        free(s_slots[i].response);
197	        s_slots[i].response = NULL;
198	    }
199	    pthread_mutex_unlock(&s_cache_lock);
200	}
