 45	 * @param prompt  User prompt text
 46	 * @param prompt_len  Length of prompt
 47	 * @return Cached response (caller must free), or NULL on miss
 48	 */
 49	char* llm_cache_get(const char* prompt, size_t prompt_len);
 50	
