 52	 * Store a response in the cache with token info.
 53	 * @param prompt  User prompt text
 54	 * @param prompt_len  Length of prompt
 55	 * @param response  Response text to cache
 56	 */
 57	void llm_cache_put(const char* prompt, size_t prompt_len,
 58	    const char* response);
 59	
