 64	 * @param prompt_len  Length of prompt
 65	 * @param total_tokens  Token count to associate
 66	 */
 67	void llm_cache_put_tokens(const char* prompt, size_t prompt_len,
 68	    int total_tokens);
 69	
 70	/**
 71	 * Get cumulative tokens saved by cache hits.
 72	 */
 73	uint32_t llm_cache_tokens_saved(void);
