        cJSON_Delete(msgs);
        cJSON_Delete(sys_msg);
        cJSON_Delete(body);
        return ERROR;
    }

    if (!cJSON_AddStringToObject(sys_msg, "role", "system") ||
        !cJSON_AddStringToObject(sys_msg, "content", system_prompt) ||
        !cJSON_InsertItemInArray(msgs, 0, sys_msg)) {
        cJSON_Delete(sys_msg);
        cJSON_Delete(msgs);
        cJSON_Delete(body);
        return ERROR;
    }

    if (!cJSON_AddItemToObject(body, "messages", msgs)) {
        cJSON_Delete(msgs);
        cJSON_Delete(body);
        return ERROR;
    }

    /* Convert tools to OpenAI format */
    cJSON* tools_arr = build_openai_tools_array(tools_json);

    if (tools_arr) {
        cJSON_AddItemToObject(body, "tools", tools_arr);
