void llm_cache_put_tokens(const char* prompt, size_t prompt_len,
    int total_tokens)
{
    if (!prompt || prompt_len == 0 || total_tokens <= 0) {
        return;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);

    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
