    pthread_mutex_lock(&s_cache_lock);
    val = s_total_hits;
    pthread_mutex_unlock(&s_cache_lock);
    return val;
}

void llm_cache_cleanup(void)
{
    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        free(s_slots[i].response);
        s_slots[i].response = NULL;
        s_slots[i].hash = 0;
        s_slots[i].ts_mono_ms = 0;
        s_slots[i].hits = 0;
        s_slots[i].tokens = 0;
    }
    s_tokens_saved = 0;
    s_total_hits = 0;
    pthread_mutex_unlock(&s_cache_lock);
}
