static bool validate_request_json(const char *post_data)
{
    size_t len = post_data ? strlen(post_data) : 0;
    size_t bad = post_data ? first_invalid_utf8(
        (const unsigned char *)post_data, len) : 0;

    if (!post_data || bad != len) {
        syslog(LOG_ERR,
            "[LLM-JSON] body bytes=%zu utf8=invalid offset=%zu value=0x%02x\n",
            len, bad, post_data ? (unsigned char)post_data[bad] : 0);
        return false;
    }

    cJSON *root = cJSON_ParseWithLength(post_data, len);
    if (!root) {
        syslog(LOG_ERR, "[LLM-JSON] body bytes=%zu utf8=ok parse=fail\n", len);
        return false;
    }

    cJSON_Delete(root);
    syslog(LOG_INFO, "[LLM-JSON] body bytes=%zu utf8=ok parse=ok\n", len);
    return true;
}

