    26	static const char* TAG = "llm_cache";
    27	
    28	typedef struct {
    29	    uint32_t hash;
    30	    char* response;
    31	    uint32_t ts; /* epoch seconds when stored */
    32	    uint32_t hits;
    33	    int tokens; /* total_tokens when cached */
    34	} llm_cache_slot_t;
    35	
    36	static llm_cache_slot_t s_slots[LLM_CACHE_SLOTS];
    37	static pthread_mutex_t s_cache_lock = PTHREAD_MUTEX_INITIALIZER;
    38	static uint32_t s_tokens_saved;
    39	static uint32_t s_total_hits;
    40	
    41	/* djb2 hash over first LLM_CACHE_KEY_LEN chars */
    42	
    43	static uint32_t djb2_hash(const char* str, size_t len)
    44	{
    45	    uint32_t h = 5381;
    46	    size_t n = len < LLM_CACHE_KEY_LEN ? len : LLM_CACHE_KEY_LEN;
    47	
    48	    for (size_t i = 0; i < n; i++) {
    49	        h = ((h << 5) + h) + (unsigned char)str[i];
    50	    }
    51	    return h;
    52	}
    53	
    54	void llm_cache_init(void)
    55	{
    56	    pthread_mutex_lock(&s_cache_lock);
    57	    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
    58	        if (s_slots[i].response) {
    59	            free(s_slots[i].response);
    60	            s_slots[i].response = NULL;
    61	        }
    62	        s_slots[i].hash = 0;
    63	        s_slots[i].ts = 0;
    64	        s_slots[i].hits = 0;
    65	        s_slots[i].tokens = 0;
    66	    }
    67	    s_tokens_saved = 0;
    68	    s_total_hits = 0;
    69	    pthread_mutex_unlock(&s_cache_lock);
    70	    syslog(LOG_INFO, "[%s] Cache initialized (%d slots, TTL %ds)\n",
    71	        TAG, LLM_CACHE_SLOTS, LLM_CACHE_TTL_SEC);
    72	}
    73	
    74	char* llm_cache_get(const char* prompt, size_t prompt_len)
    75	{
    76	    if (!prompt || prompt_len == 0) {
    77	        return NULL;
    78	    }
    79	
    80	    uint32_t h = djb2_hash(prompt, prompt_len);
    81	    uint32_t now = (uint32_t)time(NULL);
    82	    char* result = NULL;
    83	
    84	    pthread_mutex_lock(&s_cache_lock);
    85	    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
    86	        llm_cache_slot_t* s = &s_slots[i];
    87	        if (s->hash == h && s->response) {
    88	            /* Check TTL */
    89	            if (now - s->ts > LLM_CACHE_TTL_SEC) {
    90	                free(s->response);
    91	                s->response = NULL;
    92	                s->hash = 0;
    93	                break;
    94	            }
    95	            result = strdup(s->response);
    96	            if (result) {
    97	                s->hits++;
    98	                s_total_hits++;
    99	                if (s->tokens > 0) {
   100	                    s_tokens_saved += (uint32_t)s->tokens;
   101	                }
   102	            }
   103	            break;
   104	        }
   105	    }
   106	    pthread_mutex_unlock(&s_cache_lock);
   107	    return result;
   108	}
   109	
   110	void llm_cache_put(const char* prompt, size_t prompt_len,
   111	    const char* response)
   112	{
   113	    if (!prompt || prompt_len == 0 || !response) {
   114	        return;
   115	    }
   116	
   117	    uint32_t h = djb2_hash(prompt, prompt_len);
   118	    uint32_t now = (uint32_t)time(NULL);
   119	
   120	    pthread_mutex_lock(&s_cache_lock);
   121	
   122	    /* Find: existing slot with same hash, or LRU (oldest ts) */
   123	    int target = 0;
   124	    uint32_t oldest_ts = UINT32_MAX;
   125	
   126	    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
   127	        if (s_slots[i].hash == h) {
   128	            target = i;
   129	            break;
   130	        }
   131	        if (s_slots[i].ts < oldest_ts) {
   132	            oldest_ts = s_slots[i].ts;
   133	            target = i;
   134	        }
   135	    }
   136	
   137	    llm_cache_slot_t* s = &s_slots[target];
   138	    if (s->response) {
   139	        free(s->response);
   140	        s->response = NULL;
   141	    }
   142	
   143	    s->response = strdup(response);
   144	    if (!s->response) {
   145	        pthread_mutex_unlock(&s_cache_lock);
   146	        return;
   147	    }
   148	    s->hash = h;
   149	    s->ts = now;
   150	    s->hits = 0;
   151	
   152	    pthread_mutex_unlock(&s_cache_lock);
   153	}
   154	
   155	void llm_cache_put_tokens(const char* prompt, size_t prompt_len,
   156	    int total_tokens)
   157	{
   158	    if (!prompt || prompt_len == 0 || total_tokens <= 0) {
   159	        return;
   160	    }
   161	
   162	    uint32_t h = djb2_hash(prompt, prompt_len);
   163	
   164	    pthread_mutex_lock(&s_cache_lock);
   165	    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
   166	        if (s_slots[i].hash == h && s_slots[i].response) {
   167	            s_slots[i].tokens = total_tokens;
   168	            break;
   169	        }
   170	    }
   171	    pthread_mutex_unlock(&s_cache_lock);
   172	}
   173	
   174	uint32_t llm_cache_tokens_saved(void)
   175	{
   176	    uint32_t val;
   177	    pthread_mutex_lock(&s_cache_lock);
   178	    val = s_tokens_saved;
   179	    pthread_mutex_unlock(&s_cache_lock);
   180	    return val;
   181	}
   182	
   183	uint32_t llm_cache_hit_count(void)
   184	{
   185	    uint32_t val;
   186	    pthread_mutex_lock(&s_cache_lock);
   187	    val = s_total_hits;
   188	    pthread_mutex_unlock(&s_cache_lock);
   189	    return val;
   190	}
   191	
   192	void llm_cache_cleanup(void)
   193	{
   194	    pthread_mutex_lock(&s_cache_lock);
   195	    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
   196	        free(s_slots[i].response);
   197	        s_slots[i].response = NULL;
   198	    }
   199	    pthread_mutex_unlock(&s_cache_lock);
   200	}
