677	cJSON* build_openai_tools_array(const char* tools_json)
678	{
679	    if (!tools_json) {
680	        return NULL;
681	    }
682	
683	    cJSON* tools_spec = cJSON_Parse(tools_json);
684	
685	    if (!tools_spec || !cJSON_IsArray(tools_spec)) {
686	        cJSON_Delete(tools_spec);
687	        return NULL;
688	    }
689	
690	    if (!agent_heap_gate_tools_parsed()) {
691	        return NULL;
692	    }
693	
694	    cJSON* tools_arr = cJSON_CreateArray();
695	    cJSON* tool_def;
696	
697	    cJSON_ArrayForEach(tool_def, tools_spec)
698	    {
699	        cJSON* wrapper = cJSON_CreateObject();
700	
701	        cJSON_AddStringToObject(wrapper, "type", "function");
702	
703	        cJSON* func = cJSON_CreateObject();
704	        cJSON* name = cJSON_GetObjectItem(tool_def, "name");
705	        cJSON* desc = cJSON_GetObjectItem(tool_def, "description");
706	        cJSON* schema = cJSON_GetObjectItem(tool_def, "input_schema");
707	
708	        if (name && cJSON_IsString(name)) {
709	            cJSON_AddStringToObject(func, "name", name->valuestring);
710	        }
711	        if (desc && cJSON_IsString(desc)) {
712	            cJSON_AddStringToObject(func, "description",
713	                desc->valuestring);
714	        }
715	        if (schema) {
716	            cJSON_AddItemToObject(func, "parameters",
717	                cJSON_Duplicate(schema, 1));
718	        } else {
719	            cJSON* empty = cJSON_CreateObject();
720	            cJSON_AddStringToObject(empty, "type", "object");
721	            cJSON_AddItemToObject(empty, "properties",
722	                cJSON_CreateObject());
723	            cJSON_AddItemToObject(func, "parameters", empty);
724	        }
725	
726	        cJSON_AddItemToObject(wrapper, "function", func);
727	        cJSON_AddItemToArray(tools_arr, wrapper);
728	    }
729	
730	    cJSON_Delete(tools_spec);
731	    return tools_arr;
732	}
