174	/* Find an exact physical node boundary. The physical walk has already
175	 * validated the heap before this helper is used for a free-list pointer. */
176	static bool agent_heap_gate_find_physical_node(
177	    const struct mm_heap_s *heap, uintptr_t target,
178	    bool *is_free, int *region_out, size_t *size_out)
179	{
180	    int regions = agent_heap_gate_region_count(heap);
181	    int region;
182	
183	    if (target == 0 || (target & (MM_ALIGN - 1)) != 0 ||
184	        regions <= 0 || regions > CONFIG_MM_REGIONS) {
185	        return false;
186	    }
187	
188	    for (region = 0; region < regions; region++) {
189	        uintptr_t start = (uintptr_t)heap->mm_heapstart[region];
190	        uintptr_t end = (uintptr_t)heap->mm_heapend[region];
191	        uintptr_t address = start;
192	        size_t steps = 0;
193	        size_t max_steps;
194	
195	        if (start == 0 || end <= start) {
196	            return false;
197	        }
198	
199	        max_steps = (end - start) / MM_SIZEOF_ALLOCNODE;
200	        if (max_steps == SIZE_MAX) {
201	            return false;
202	        }
203	        max_steps++;
204	
205	        while (address < end) {
206	            size_t remaining = end - address;
207	            struct mm_allocnode_s *node;
208	            size_t size;
209	
210	            if (steps >= max_steps) {
211	                return false;
212	            }
213	            steps++;
214	
215	            if (remaining < MM_SIZEOF_ALLOCNODE ||
216	                (address & (MM_ALIGN - 1)) != 0) {
217	                return false;
218	            }
219	
220	            node = (struct mm_allocnode_s *)address;
221	            size = MM_SIZEOF_NODE(node);
222	            if (size < MM_SIZEOF_ALLOCNODE ||
223	                (size & (MM_ALIGN - 1)) != 0 || size > remaining ||
224	                size > UINTPTR_MAX - address) {
225	                return false;
226	            }
227	
228	            if (address == target) {
229	                *is_free = MM_NODE_IS_FREE(node);
230	                *region_out = region;
231	                *size_out = size;
232	                return true;
233	            }
234	
235	            address += size;
236	        }
237	
238	        if (address != end && target < end) {
239	            return false;
240	        }
241	    }
242	
243	    return false;
244	}
