550	                agent_heap_gate_capture_links(result, current);
551	                agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_TERM,
552	                    -1, current, 0);
553	                goto done;
554	            }
555	            current_bin = sentinel;
556	            expected_sentinel++;
557	        } else if (!agent_heap_gate_find_physical_node(heap,
558	                       (uintptr_t)current, &is_free, &region, &size) ||
559	                   !is_free) {
560	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
561	                -1, current, 0);
562	            goto done;
563	        } else {
564	            if (size < MM_MIN_CHUNK || mm_size2ndx(size) != current_bin) {
565	                agent_heap_gate_capture_links(result, current);
566	                agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_BIN,
567	                    region, current, size);
568	                goto done;
569	            }
570	            if (!agent_heap_gate_add_count(&list_nodes)) {
571	                agent_heap_gate_fail(result,
