573	                    current, size);
574	                goto done;
575	            }
576	        }
577	
578	        if ((uintptr_t)current->blink != (uintptr_t)previous) {
579	            agent_heap_gate_capture_links(result, current);
580	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
581	                current, 0);
582	            goto done;
583	        }
584	        if (!agent_heap_gate_is_valid_link(heap, current->flink)) {
585	            agent_heap_gate_capture_links(result, current);
586	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
587	                -1, current, 0);
588	            goto done;
589	        }
590	
591	        previous = current;
592	        current = current->flink;
593	    }
594	
595	    if (expected_sentinel != MM_NNODES || list_nodes != physical_free_nodes) {
596	        agent_heap_gate_fail(result,
597	            expected_sentinel != MM_NNODES ? AGENT_HEAP_GATE_FREELIST_TERM :
