    if (list_limit == 0 || heap->mm_nodelist[0].blink != NULL) {
        agent_heap_gate_capture_links(result, &heap->mm_nodelist[0]);
        agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
            &heap->mm_nodelist[0], 0);
        goto done;
    }

    previous = &heap->mm_nodelist[0];
    current = previous->flink;
    while (current != NULL) {
        int sentinel = agent_heap_gate_sentinel_index(heap, current);
        bool is_free;
        int region;
        size_t size;

        if (steps >= list_limit) {
            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_CYCLE,
                -1, current, 0);
            goto done;
        }
        steps++;

        if (sentinel >= 0) {
            if (sentinel != expected_sentinel ||
                expected_sentinel >= MM_NNODES) {
                agent_heap_gate_capture_links(result, current);
                agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_TERM,
                    -1, current, 0);
                goto done;
            }
            current_bin = sentinel;
            expected_sentinel++;
        } else if (!agent_heap_gate_find_physical_node(heap,
                       (uintptr_t)current, &is_free, &region, &size) ||
                   !is_free) {
            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
                -1, current, 0);
            goto done;
        } else {
            if (size < MM_MIN_CHUNK || mm_size2ndx(size) != current_bin) {
                agent_heap_gate_capture_links(result, current);
                agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_BIN,
                    region, current, size);
                goto done;
            }
            if (!agent_heap_gate_add_count(&list_nodes)) {
                agent_heap_gate_fail(result,
                    AGENT_HEAP_GATE_FREELIST_MEMBERSHIP, region,
                    current, size);
                goto done;
            }
        }

        if ((uintptr_t)current->blink != (uintptr_t)previous) {
            agent_heap_gate_capture_links(result, current);
            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
                current, 0);
            goto done;
        }
        if (!agent_heap_gate_is_valid_link(heap, current->flink)) {
            agent_heap_gate_capture_links(result, current);
            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
                -1, current, 0);
            goto done;
        }

        previous = current;
        current = current->flink;
    }

    if (expected_sentinel != MM_NNODES || list_nodes != physical_free_nodes) {
        agent_heap_gate_fail(result,
            expected_sentinel != MM_NNODES ? AGENT_HEAP_GATE_FREELIST_TERM :
                                             AGENT_HEAP_GATE_FREELIST_MEMBERSHIP,
            -1, previous, 0);
        goto done;
    }

    /* Rescan the validated global chain for every physical free node. */
    {
        int regions = agent_heap_gate_region_count(heap);
        int region;

        for (region = 0; region < regions; region++) {
            uintptr_t address = (uintptr_t)heap->mm_heapstart[region];
            uintptr_t end = (uintptr_t)heap->mm_heapend[region];
            size_t physical_steps = 0;
            size_t physical_limit = (end - address) /
                                    MM_SIZEOF_ALLOCNODE;

            if (physical_limit == SIZE_MAX) {
                agent_heap_gate_fail(result, AGENT_HEAP_GATE_NODE_BOUNDS,
                    region, (struct mm_freenode_s *)address, 0);
                goto done;
            }
            physical_limit++;

            while (address < end) {
                struct mm_allocnode_s *node =
                    (struct mm_allocnode_s *)address;
                size_t size = MM_SIZEOF_NODE(node);

                if (physical_steps >= physical_limit) {
                    agent_heap_gate_fail(result,
                        AGENT_HEAP_GATE_NODE_BOUNDS, region,
                        (struct mm_freenode_s *)address, 0);
                    goto done;
                }
                physical_steps++;

                if (MM_NODE_IS_FREE(node)) {
                    size_t matches;

                    if (!agent_heap_gate_count_membership(heap, address,
                        list_limit, &matches, result) || matches != 1) {
                        agent_heap_gate_fail(result,
                            AGENT_HEAP_GATE_FREELIST_MEMBERSHIP, region,
                            (struct mm_freenode_s *)node, size);
                        goto done;
                    }
                }
                address += size;
            }
        }
    }

done:
    nxrmutex_unlock(&heap->mm_lock);
    return result->reason == AGENT_HEAP_GATE_NONE;
}

static bool agent_heap_gate_tools_parsed(void)
{
    struct agent_heap_gate_result_s result;
    bool pass = agent_heap_gate_check(&result);

    if (pass) {
        syslog(LOG_INFO, "[HEAP-GATE] TOOLS_PARSED PASS\n");
